static COUNTER: AtomicU64 = AtomicU64::new(0);

/// The longest single path component the platform accepts: 255 bytes on unix, 255 UTF-16 code
/// units on Windows. Reads, listings, stats and removals accept any name up to this length.
pub const PLATFORM_NAME_LIMIT: usize = 255;

/// The default cap on names a `StateDir` *creates*: 200 bytes on unix, 255 UTF-16 units on
/// Windows. On unix 200 leaves room for the `.<name>.rktmp-<pid>-<n>-<attempt>` temp name (at
/// most 42 bytes beyond the name) inside 255 for names written by older versions; temp names now
/// carry at most 64 bytes of the name, so [`StateOptions::max_name_len`] can raise the cap to
/// [`PLATFORM_NAME_LIMIT`].
#[cfg(not(windows))]
pub const DEFAULT_WRITE_NAME_LEN: usize = 200;
/// See the unix constant: Windows has always accepted names up to the platform limit.
#[cfg(windows)]
pub const DEFAULT_WRITE_NAME_LEN: usize = PLATFORM_NAME_LIMIT;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EntryKind {
    File,
    Dir,
    Symlink,
    Other,
}

#[derive(Clone, Copy, Debug)]
pub struct EntryStat {
    pub kind: EntryKind,
    pub size: u64,
    pub dev: u64,
    pub ino: u64,
    pub mode: u32,
    pub modified_unix_ms: u64,
}

/// One directory entry from [`StateDir::list_entries`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DirEntry {
    /// The entry name. A name that is not valid Unicode is returned lossily (U+FFFD) and cannot
    /// be addressed by the other methods.
    pub name: String,
    /// What the entry is, without following it. On Windows any reparse point (symlink, junction,
    /// mount point, placeholder) is [`EntryKind::Symlink`].
    pub kind: EntryKind,
}

/// How a [`StateDir`] is opened or created. `StateOptions::default()` is what
/// [`StateDir::open`] and [`StateDir::create`] use. Children made by [`StateDir::child`] inherit
/// the options.
#[derive(Clone, Debug)]
pub struct StateOptions {
    /// Windows access control on directories and files this `StateDir` creates (including
    /// missing ancestors):
    ///
    /// - [`Privacy::OwnerOnly`] (default): a protected owner-only ACL, set at creation. Beware
    ///   that if the `StateDir` is the first creator of an application data root, that root gets
    ///   the protected ACL too and every later child created under it inherits it (other
    ///   accounts, services and backup agents lose access). Create the data root first, or use
    ///   the option below.
    /// - [`Privacy::OwnerOnlyUnixInheritWindows`] or [`Privacy::Inherit`]: no ACL step on
    ///   Windows, so new objects carry the parent's inherited ACL, the same meaning these have for
    ///   atomic writes.
    ///
    /// Unix ignores this: directories are always created `0700`, files `0600`, and a pinned
    /// directory must be owned by the user and not group/other writable.
    /// [`StateDir::create_new_empty`] requires `OwnerOnly` on Windows and refuses inheritance.
    pub privacy: Privacy,
    /// Windows only: open the pinned directory with `FILE_SHARE_DELETE`, so other handles may
    /// rename or delete the directory (or an ancestor) while this `StateDir` is open. Operations
    /// stay handle-relative and keep acting on the original directory, but
    /// [`StateDir::path`] then names whatever is at that path now, so use no path-based call on
    /// it. Default `false`: the directory cannot be renamed or removed while open, so the path
    /// stays true. Unix descriptors always behave as if this were `true`.
    pub allow_rename_while_open: bool,
    /// Longest name this `StateDir` creates, clamped to `1..=`[`PLATFORM_NAME_LIMIT`]. `None` is
    /// [`DEFAULT_WRITE_NAME_LEN`]. Reads and listings are never limited below the platform limit.
    pub max_name_len: Option<usize>,
    /// Behaviour when `F_FULLFSYNC` is unavailable (Apple only). Default
    /// [`SyncPolicy::Fallback`]; [`SyncPolicy::Strict`] makes writes fail instead.
    pub sync: SyncPolicy,
}

impl Default for StateOptions {
    fn default() -> Self {
        Self {
            privacy: Privacy::OwnerOnly,
            allow_rename_while_open: false,
            max_name_len: None,
            sync: SyncPolicy::Fallback,
        }
    }
}

impl StateOptions {
    fn write_cap(&self) -> usize {
        self.max_name_len
            .unwrap_or(DEFAULT_WRITE_NAME_LEN)
            .clamp(1, PLATFORM_NAME_LIMIT)
    }

    #[cfg_attr(not(windows), allow(dead_code))]
    fn inherit_acl(&self) -> bool {
        self.privacy != Privacy::OwnerOnly
    }
}

fn check_name(name: &str, limit: usize) -> Result<()> {
    let bad = name.is_empty()
        || name == "."
        || name == ".."
        || name.bytes().any(|b| b == b'/' || b == b'\\' || b == 0);
    #[cfg(not(windows))]
    let bad = bad || name.len() > limit;
    #[cfg(windows)]
    let bad = bad || !sys::valid_component(name, limit);
    if bad {
        return Err(FsError::BadName(name.to_string()));
    }
    Ok(())
}

/// Entry names are single path components: no separators, no NUL, not `.`/`..`, within the
/// default write cap ([`DEFAULT_WRITE_NAME_LEN`]), and not shaped like a temp name this crate
/// generates (`.<name>.rktmp-<pid>-<n>-<attempt>`), which a sweep would delete.
pub fn validate_name(name: &str) -> Result<()> {
    check_name(name, DEFAULT_WRITE_NAME_LEN)?;
    crate::atomic::reject_reserved_name(name)
}

/// The prefix of `name` used in a temp name: at most 64 bytes, cut at a character boundary, so a
/// temp name fits the platform limit however long the real name is.
fn temp_prefix(name: &str) -> &str {
    let mut end = name.len().min(64);
    while !name.is_char_boundary(end) {
        end -= 1;
    }
    &name[..end]
}

/// `EntryKind` from Windows file attributes: reparse point, then directory, else file.
#[cfg_attr(not(windows), allow(dead_code))]
fn kind_from_attributes(attributes: u32) -> EntryKind {
    const DIRECTORY: u32 = 0x10;
    const REPARSE_POINT: u32 = 0x400;
    if attributes & REPARSE_POINT != 0 {
        EntryKind::Symlink
    } else if attributes & DIRECTORY != 0 {
        EntryKind::Dir
    } else {
        EntryKind::File
    }
}

/// Flush `file`, honouring the policy. Under the `testing` feature a thread can pretend the
/// strongest flush is unavailable ([`testing::without_full_sync`]).
fn flush(file: &File, policy: SyncPolicy) -> std::io::Result<SyncLevel> {
    #[cfg(feature = "testing")]
    if testing::full_sync_unavailable() {
        return crate::atomic::sync_ladder(
            policy,
            || Err(std::io::Error::from(std::io::ErrorKind::Unsupported)),
            || file.sync_all(),
            || file.sync_all(),
        );
    }
    durable_sync_with(file, policy)
}

#[derive(Debug)]
pub struct StateDir {
    dir: sys::Dir,
    path: PathBuf,
    options: StateOptions,
    /// Opened by [`StateDir::open_shared`]: the pinned directory (and children found below it) need
    /// not be private. Inherited by [`StateDir::child`].
    shared: bool,
}

impl StateDir {
    /// Pin an existing directory.
    pub fn open(path: &Path) -> Result<Self> {
        Self::open_with(path, &StateOptions::default())
    }

    /// [`open`](Self::open) with explicit [`StateOptions`].
    pub fn open_with(path: &Path, options: &StateOptions) -> Result<Self> {
        Ok(Self {
            dir: sys::Dir::pin(path, false, options, false)?,
            path: path.to_path_buf(),
            options: options.clone(),
            shared: false,
        })
    }

    /// Pin an existing directory **that need not be private**: [`open`](Self::open) refuses a
    /// directory writable by group or others ([`FsError::TooPermissive`]); this accepts it. For a
    /// directory the user chose and this program does not own the policy of (an attachment folder, a
    /// downloads folder, a shared workspace), where the private-directory rule would make the pin
    /// impossible.
    ///
    /// Everything else is as strict as [`open`](Self::open): every component is opened without
    /// following a symlink, the leaf must be a real directory owned by the effective user (Unix), and
    /// every operation stays descriptor- or handle-relative to the pinned directory, so a swapped or
    /// symlinked path cannot redirect it. What is given up is only the assumption that nobody else
    /// can change the directory's *entries*: another user able to write there can create, rename or
    /// remove names (a world-writable directory without the sticky bit even lets them replace yours).
    /// Reads still refuse symlinks and non-regular files; write only what you can lose. Children made
    /// by [`child`](Self::child) inherit this policy. Windows checks no ACL or mode when pinning, so
    /// there this is the same as [`open`](Self::open).
    pub fn open_shared(path: &Path) -> Result<Self> {
        Self::open_shared_with(path, &StateOptions::default())
    }

    /// [`open_shared`](Self::open_shared) with explicit [`StateOptions`].
    pub fn open_shared_with(path: &Path, options: &StateOptions) -> Result<Self> {
        Ok(Self {
            dir: sys::Dir::pin(path, false, options, true)?,
            path: path.to_path_buf(),
            options: options.clone(),
            shared: true,
        })
    }

    /// Create the directory (and missing ancestors, owner-only, through descriptor-relative
    /// `mkdirat`) if needed, then pin it.
    pub fn create(path: &Path) -> Result<Self> {
        Self::create_with(path, &StateOptions::default())
    }

    /// [`create`](Self::create) with explicit [`StateOptions`].
    pub fn create_with(path: &Path, options: &StateOptions) -> Result<Self> {
        Ok(Self {
            dir: sys::Dir::pin(path, true, options, false)?,
            path: path.to_path_buf(),
            options: options.clone(),
            shared: false,
        })
    }

    /// Like [`create`](Self::create) but resolves symlinks in the *parent* first (for example
    /// macOS `/var` -> `/private/var`). The final component must still be a real directory.
    pub fn create_in_resolved_parent(path: &Path) -> Result<Self> {
        Self::create_in_resolved_parent_with(path, &StateOptions::default())
    }

    /// [`create_in_resolved_parent`](Self::create_in_resolved_parent) with explicit
    /// [`StateOptions`].
    pub fn create_in_resolved_parent_with(path: &Path, options: &StateOptions) -> Result<Self> {
        let name = path
            .file_name()
            .ok_or_else(|| FsError::BadName(path.display().to_string()))?;
        let parent = match path.parent() {
            Some(p) if !p.as_os_str().is_empty() => {
                p.canonicalize().map_err(|e| FsError::io(p, e))?
            }
            _ => std::env::current_dir().map_err(|e| FsError::io(path, e))?,
        };
        Self::create_with(&parent.join(name), options)
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    /// The options this directory was opened with.
    pub fn options(&self) -> &StateOptions {
        &self.options
    }

    /// Create-or-open a direct child directory (owner-only), pinned relative to this one. The
    /// name is held to the write cap, since the call may create it. A directory this call
    /// creates is made durable like a write: on unix this directory is synced, and a failure is
    /// [`FsError::DirSyncFailed`] with the child already created. A child that already exists is
    /// returned as it is, with no sync (see the module table), and so is one a racing creator
    /// made first.
    pub fn child(&self, name: &str) -> Result<StateDir> {
        check_name(name, self.options.write_cap())?;
        Ok(Self {
            dir: self.dir.child(name, self.options.sync, self.shared)?,
            path: self.path.join(name),
            options: self.options.clone(),
            shared: self.shared,
        })
    }

    pub fn stat(&self, name: &str) -> Result<Option<EntryStat>> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        self.dir.stat(name)
    }

    pub fn exists(&self, name: &str) -> Result<bool> {
        Ok(self.stat(name)?.is_some())
    }

    /// Read a regular file (never through a symlink), refusing anything over `max_bytes`. Any
    /// existing name up to [`PLATFORM_NAME_LIMIT`] can be read, including one longer than this
    /// directory's write cap.
    pub fn read(&self, name: &str, max_bytes: u64) -> Result<Vec<u8>> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        let path = self.path.join(name);
        let mut file = self.open_read(name, &crate::handle::ReadOptions::new())?;
        let meta = file.metadata().map_err(|e| FsError::io(&path, e))?;
        if meta.len() > max_bytes {
            return Err(FsError::TooLarge {
                path,
                size: meta.len(),
                limit: max_bytes,
            });
        }
        let mut out = Vec::with_capacity(usize::try_from(meta.len()).unwrap_or(0));
        // One byte past the limit proves the file outgrew it. `u64::MAX` means "no limit", so
        // the sum saturates instead of wrapping to a zero-byte read.
        (&mut file)
            .take(max_bytes.saturating_add(1))
            .read_to_end(&mut out)
            .map_err(|e| FsError::io(&path, e))?;
        if out.len() as u64 > max_bytes {
            return Err(FsError::TooLarge {
                path,
                size: out.len() as u64,
                limit: max_bytes,
            });
        }
        Ok(out)
    }

    /// Open a regular file in this directory for reading and return the handle.
    ///
    /// The entry is opened relative to the pinned directory without following a symlink or reparse
    /// point ([`FsError::Symlink`]); anything that is not a regular file is [`FsError::NotAFile`] (a
    /// FIFO or device is never waited on); [`ReadOptions`](crate::handle::ReadOptions) adds the
    /// checks for more than one hard link ([`FsError::HardLinked`]), owner-only access on the open
    /// handle, and, on Windows, read-only sharing
    /// (no other handle may write, delete or rename the file while it is open). The handle is the
    /// caller's to read, query ([`crate::handle::final_path`], [`crate::FileKey::of_file`]) and drop.
    /// Any existing name up to [`PLATFORM_NAME_LIMIT`] can be opened.
    pub fn open_read(&self, name: &str, options: &crate::handle::ReadOptions) -> Result<File> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        let shown = self.path.join(name);
        let file = self.dir.open_read_with(name, options)?;
        crate::handle::finish_read_open(file, &shown, options)
    }

    /// Remove an **empty directory** child. A symlink, junction or file at `name` is refused (a
    /// symlink is [`FsError::Symlink`] on Windows and `NotADirectory` on unix: it is never followed
    /// and never removed here, use [`remove_link`](Self::remove_link)); a directory that still holds
    /// entries fails with the OS error (`ENOTEMPTY`, `ERROR_DIR_NOT_EMPTY`). Missing is `Ok(false)`.
    /// Durable like [`remove`](Self::remove): a failed directory sync is [`FsError::DirSyncFailed`]
    /// with the directory already gone.
    pub fn remove_dir(&self, name: &str) -> Result<bool> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        match self.dir.remove_dir(name) {
            Ok(()) => {}
            Err(e) if e.is_not_found() => return Ok(false),
            Err(e) => return Err(e),
        }
        self.dir
            .sync(self.options.sync)
            .map_err(|source| FsError::DirSyncFailed {
                path: self.path.join(name),
                source,
            })?;
        Ok(true)
    }

    /// Remove a **symlink or junction** child, the link itself and never its target. Unix unlinks the
    /// symlink; Windows opens the reparse point (not its target) and deletes it through that handle,
    /// which removes a junction or directory symlink without touching what it points at. An entry
    /// that is not a link (a file, a directory) is refused as `InvalidInput`, so this cannot remove
    /// real content by mistake. Missing is `Ok(false)`. Durable like [`remove`](Self::remove).
    pub fn remove_link(&self, name: &str) -> Result<bool> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        match self.dir.remove_link(name) {
            Ok(()) => {}
            Err(e) if e.is_not_found() => return Ok(false),
            Err(e) => return Err(e),
        }
        self.dir
            .sync(self.options.sync)
            .map_err(|source| FsError::DirSyncFailed {
                path: self.path.join(name),
                source,
            })?;
        Ok(true)
    }

    /// Like [`read`](Self::read) but `Ok(None)` when the entry does not exist.
    pub fn read_opt(&self, name: &str, max_bytes: u64) -> Result<Option<Vec<u8>>> {
        match self.read(name, max_bytes) {
            Ok(bytes) => Ok(Some(bytes)),
            Err(e) if e.is_not_found() => Ok(None),
            Err(e) => Err(e),
        }
    }

    /// Exclusively create an empty regular file at its final name and return its write handle.
    ///
    /// This is for permanent lock files: creation stays relative to this pinned directory,
    /// never creates a second hard link, and never replaces an existing name. An existing name
    /// returns [`FsError::AlreadyExists`]. Names obey the write cap and reserved-temp rules.
    /// The returned handle passes the regular-file, single-link, and owner-only handle checks of
    /// [`open_read`](Self::open_read) with `require_single_link(true).require_owner_only(true)`.
    /// On Windows, [`StateOptions::privacy`] must be [`Privacy::OwnerOnly`]; an inheritance option
    /// is refused before creation. Platforms other than Unix and Windows are likewise refused
    /// before creation ([`FsError::Unavailable`]).
    ///
    /// No file or directory flush is performed. Use [`write_new`](Self::write_new) for durable
    /// content publication. This method preserves process-lifetime lock identity; it does not
    /// promise that the directory entry survives power loss.
    ///
    /// A check can fail after the name becomes visible. Such a failure leaves the empty entry
    /// in place, closes its handle, and returns the error: removing a visible lock could let
    /// another caller lock a different inode. An error is not permission to remove or replace
    /// the name. Existing locks must be opened through this same pinned directory with
    /// `require_single_link(true).require_owner_only(true)`: an earlier error may have left an
    /// unverified file. Neither an existing name nor a single link proves private access.
    /// All handle checks describe the state now; later changes are not prevented.
    pub fn create_new_empty(&self, name: &str) -> Result<File> {
        #[cfg(not(any(unix, windows)))]
        {
            let _ = name;
            Err(FsError::Unavailable(
                "direct private empty-file creation requires Unix or Windows",
            ))
        }
        #[cfg(any(unix, windows))]
        {
            #[cfg(windows)]
            if self.options.inherit_acl() {
                return Err(FsError::Unavailable(
                    "direct private empty-file creation requires Privacy::OwnerOnly",
                ));
            }
            check_name(name, self.options.write_cap())?;
            crate::atomic::reject_reserved_name(name)?;
            let shown = self.path.join(name);
            let file = self
                .dir
                .create_new(name, true)
                .map_err(|error| match error {
                    FsError::AlreadyExists(_) => FsError::AlreadyExists(shown.clone()),
                    other => other,
                })?;
            crate::handle::finish_read_open(
                file,
                &shown,
                &crate::handle::ReadOptions::new()
                    .require_single_link(true)
                    .require_owner_only(true),
            )
        }
    }

    /// Atomically create or replace `name` (owner-only, file and directory synced). A failed
    /// directory sync is [`FsError::ReplacedButDirSyncFailed`]: the content is in place but the
    /// rename may not survive power loss. Windows has no directory flush; see the module docs.
    pub fn write(&self, name: &str, bytes: &[u8]) -> Result<()> {
        self.publish(name, bytes, true).map(|_| ())
    }

    /// [`write`](Self::write) that also reports the weakest [`SyncLevel`] reached by the file
    /// and directory syncs. Windows reports only the file flush.
    pub fn write_reporting(&self, name: &str, bytes: &[u8]) -> Result<SyncLevel> {
        self.publish(name, bytes, true)
    }

    /// Atomically create `name`, failing with [`FsError::AlreadyExists`] rather than replacing.
    /// A failed directory sync is [`FsError::ReplacedButDirSyncFailed`] (the entry exists).
    pub fn write_new(&self, name: &str, bytes: &[u8]) -> Result<()> {
        self.publish(name, bytes, false).map(|_| ())
    }

    /// [`write_new`](Self::write_new) that reports the weakest [`SyncLevel`] reached.
    pub fn write_new_reporting(&self, name: &str, bytes: &[u8]) -> Result<SyncLevel> {
        self.publish(name, bytes, false)
    }

    fn publish(&self, name: &str, bytes: &[u8], replace: bool) -> Result<SyncLevel> {
        check_name(name, self.options.write_cap())?;
        // A name shaped like one of our temp names would be deleted by `sweep_temps`.
        crate::atomic::reject_reserved_name(name)?;
        let final_path = self.path.join(name);
        let (temp, mut file) = self.create_temp(name)?;
        let result = (|| -> Result<SyncLevel> {
            file.write_all(bytes)
                .map_err(|e| FsError::io(&final_path, e))?;
            let file_level =
                flush(&file, self.options.sync).map_err(|e| FsError::io(&final_path, e))?;
            drop(file);
            if replace {
                // Never replace a symlinked or non-file destination through the rename.
                if let Some(existing) = self.dir.stat(name)? {
                    if existing.kind != EntryKind::File {
                        return Err(FsError::NotAFile(final_path.clone()));
                    }
                }
                self.dir.rename_replace(&temp, name)?;
            } else {
                self.dir.link_new(&temp, name).map_err(|e| match e {
                    FsError::AlreadyExists(_) => FsError::AlreadyExists(final_path.clone()),
                    other => other,
                })?;
                let _ = self.dir.unlink(&temp);
            }
            // Past this point the entry is published; a failure no longer removes it.
            match self.dir.sync(self.options.sync) {
                Ok(Some(dir_level)) => Ok(file_level.min(dir_level)),
                Ok(None) => Ok(file_level),
                Err(source) => Err(FsError::ReplacedButDirSyncFailed {
                    path: final_path.clone(),
                    source,
                }),
            }
        })();
        if result.is_err() {
            let _ = self.dir.unlink(&temp);
        }
        result
    }

    fn create_temp(&self, name: &str) -> Result<(String, File)> {
        let prefix = temp_prefix(name);
        for attempt in 0..crate::atomic::TEMP_ATTEMPTS {
            let n = COUNTER.fetch_add(1, Ordering::Relaxed);
            let temp = format!(".{prefix}{TEMP_MARKER}{}-{n}-{attempt}", std::process::id());
            match self.dir.create_new(&temp, false) {
                Ok(file) => return Ok((temp, file)),
                Err(FsError::AlreadyExists(_)) => continue,
                Err(e) => return Err(e),
            }
        }
        Err(FsError::AlreadyExists(self.path.join(name)))
    }

    /// Remove a file. Unix removes a symlink itself; Windows refuses reparse points.
    /// Missing is `Ok(false)`. The removal is made durable like a write: a failed directory sync
    /// is [`FsError::DirSyncFailed`] with the entry already gone.
    pub fn remove(&self, name: &str) -> Result<bool> {
        check_name(name, PLATFORM_NAME_LIMIT)?;
        match self.dir.unlink(name) {
            Ok(()) => {}
            Err(e) if e.is_not_found() => return Ok(false),
            Err(e) => return Err(e),
        }
        self.dir
            .sync(self.options.sync)
            .map_err(|source| FsError::DirSyncFailed {
                path: self.path.join(name),
                source,
            })?;
        Ok(true)
    }

    /// Names of direct children, capped at `limit` entries (error past the cap). Every existing
    /// name is returned, including one longer than the write cap.
    pub fn list(&self, limit: usize) -> Result<Vec<String>> {
        Ok(self
            .dir
            .entries(limit)?
            .into_iter()
            .map(|entry| entry.name)
            .collect())
    }

    /// Direct children with their [`EntryKind`], capped at `limit` entries (error past the cap).
    /// The kind comes from the directory entry itself (`d_type` on unix, the attributes in
    /// `FILE_ID_BOTH_DIR_INFO` on Windows), so no per-entry stat is made; on unix an entry whose
    /// filesystem reports no type (`DT_UNKNOWN`) gets one descriptor-relative `fstatat`.
    pub fn list_entries(&self, limit: usize) -> Result<Vec<DirEntry>> {
        self.dir.entries(limit)
    }

    /// Remove generated regular temp files left by writers confirmed dead. `max_age` remains for
    /// source compatibility but cannot override liveness: current, live, and unqueryable PIDs
    /// survive regardless of age. Only complete generated temp names
    /// (`.<name>.rktmp-<pid>-<n>-<attempt>`, or the longer `atomic_write` form) are considered,
    /// and `write`/`write_new` refuse those names as targets, so a committed record is never
    /// swept. The pinned directory rechecks the observed regular-file identity before removal;
    /// Unix cannot make that comparison and `unlinkat` one operation against arbitrary concurrent
    /// path replacement. Returns how many were removed.
    pub fn sweep_temps(&self, max_age: std::time::Duration) -> Result<usize> {
        let _ = max_age;
        #[cfg(windows)]
        {
            self.dir.sweep_temps()
        }
        #[cfg(not(windows))]
        {
            self.sweep_temps_path()
        }
    }

    #[cfg(not(windows))]
    fn sweep_temps_path(&self) -> Result<usize> {
        let mut removed = 0;
        for DirEntry { name, .. } in self.dir.entries(usize::MAX)? {
            // Only a complete generated temp name is ever reclaimed; a committed record that
            // merely contains the marker (`invoice.rktmp-1-final`) is left alone.
            let Some(pid) = crate::atomic::generated_temp_pid(&name) else {
                continue;
            };
            if !crate::atomic::confirmed_dead_writer(pid) {
                continue;
            }
            // Check again directly before descriptor-relative deletion. A failed query is not
            // proof of death, even if the generated name is old.
            if crate::atomic::confirmed_dead_writer(pid)
                && self.dir.unlink_regular(&name).unwrap_or(false)
            {
                removed += 1;
            }
        }
        Ok(removed)
    }
}

/// Fault injection for consumer tests (feature `testing`, off by default; debug builds only).
/// Hooks are per thread and removed when their guard drops.
#[cfg(feature = "testing")]
pub mod testing {
    use std::cell::{Cell, RefCell};
    use std::fs::File;
    use std::io;

    type EmptyCreateHook = Box<dyn Fn(&File) -> crate::Result<()>>;

    /// One directory-level step of a `StateDir` operation, in the order it happened. Recorded on
    /// Unix only (Windows makes no directory sync call).
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub enum DirEvent {
        /// `mkdirat` created a directory with this single-component name.
        Created(String),
        /// A directory sync was attempted on the directory whose inode number is this (whether or
        /// not [`fail_dir_sync`] made it fail).
        Synced(u64),
    }

    thread_local! {
        static EMPTY_CREATE_HOOK: RefCell<Option<EmptyCreateHook>> = const { RefCell::new(None) };
        static DIR_SYNC_FAILURE: RefCell<Option<io::ErrorKind>> = const { RefCell::new(None) };
        static DIR_EVENTS: RefCell<Vec<DirEvent>> = const { RefCell::new(Vec::new()) };
        static DIR_SYNCS: Cell<usize> = const { Cell::new(0) };
        static FULL_SYNC_UNAVAILABLE: Cell<bool> = const { Cell::new(false) };
        static FALLBACK_STATS: Cell<usize> = const { Cell::new(0) };
    }

    /// Removes the hook when dropped.
    pub struct HookGuard(fn());

    impl Drop for HookGuard {
        fn drop(&mut self) {
            (self.0)();
        }
    }

    /// Observe or fail direct empty-file creation immediately after the final name is created,
    /// before post-creation checks. The hook runs only for [`super::StateDir::create_new_empty`].
    /// Returning an error leaves the visible entry in place. This tests publication boundaries
    /// without a timing race or a different filesystem implementation.
    pub fn on_empty_created(hook: impl Fn(&File) -> crate::Result<()> + 'static) -> HookGuard {
        EMPTY_CREATE_HOOK.with(|slot| *slot.borrow_mut() = Some(Box::new(hook)));
        HookGuard(|| EMPTY_CREATE_HOOK.with(|slot| *slot.borrow_mut() = None))
    }

    pub(super) fn after_empty_create(file: &File) -> crate::Result<()> {
        EMPTY_CREATE_HOOK.with(|slot| match slot.borrow().as_ref() {
            Some(hook) => hook(file),
            None => Ok(()),
        })
    }

    /// Make every directory sync this thread's `StateDir` operations perform fail with `kind`
    /// (standing in for the OS call) until the guard drops. Unix only: Windows makes no
    /// directory sync call.
    pub fn fail_dir_sync(kind: io::ErrorKind) -> HookGuard {
        DIR_SYNC_FAILURE.with(|f| *f.borrow_mut() = Some(kind));
        HookGuard(|| DIR_SYNC_FAILURE.with(|f| *f.borrow_mut() = None))
    }

    /// Pretend the strongest flush (`F_FULLFSYNC`) is unavailable for this thread's `StateDir`
    /// syncs, on any platform, so [`SyncPolicy`](crate::SyncPolicy) can be exercised.
    pub fn without_full_sync() -> HookGuard {
        FULL_SYNC_UNAVAILABLE.with(|f| f.set(true));
        HookGuard(|| FULL_SYNC_UNAVAILABLE.with(|f| f.set(false)))
    }

    /// Directory syncs attempted on this thread since it started.
    pub fn dir_sync_count() -> usize {
        DIR_SYNCS.with(Cell::get)
    }

    /// The directory creations and directory syncs this thread's `StateDir` operations made, in
    /// order, since the last call. Empties the log. Tests assert the order to prove a directory
    /// is published (its parent synced) before the walk descends into it.
    pub fn take_dir_events() -> Vec<DirEvent> {
        DIR_EVENTS.with(|events| std::mem::take(&mut *events.borrow_mut()))
    }

    /// Per-entry `fstatat` fallbacks made by listings on this thread (entries whose filesystem
    /// reported no type). Zero on filesystems that report `d_type`.
    pub fn fallback_stat_count() -> usize {
        FALLBACK_STATS.with(Cell::get)
    }

    #[cfg(unix)]
    pub(super) fn record_created(name: &str) {
        DIR_EVENTS.with(|events| {
            events
                .borrow_mut()
                .push(DirEvent::Created(name.to_string()))
        });
    }

    #[cfg(unix)]
    pub(super) fn before_dir_sync(dir: &std::fs::File) -> Option<io::Error> {
        use std::os::unix::fs::MetadataExt;
        DIR_SYNCS.with(|c| c.set(c.get() + 1));
        if let Ok(meta) = dir.metadata() {
            DIR_EVENTS.with(|events| events.borrow_mut().push(DirEvent::Synced(meta.ino())));
        }
        DIR_SYNC_FAILURE.with(|f| {
            f.borrow()
                .map(|kind| io::Error::new(kind, "injected directory sync failure"))
        })
    }

    #[cfg(unix)]
    pub(super) fn count_fallback_stat() {
        FALLBACK_STATS.with(|c| c.set(c.get() + 1));
    }

    pub(super) fn full_sync_unavailable() -> bool {
        FULL_SYNC_UNAVAILABLE.with(Cell::get)
    }
}

#[cfg(unix)]
mod sys {
    use super::{DirEntry, EntryKind, EntryStat, StateOptions};
    use crate::atomic::{SyncLevel, SyncPolicy};
    use crate::error::{FsError, Result};
    use std::ffi::{CStr, CString};
    use std::fs::File;
    use std::io;
    use std::os::unix::ffi::OsStrExt;
    use std::os::unix::fs::MetadataExt;
    use std::os::unix::io::{AsRawFd, FromRawFd, IntoRawFd, RawFd};
    use std::path::Path;

    #[derive(Debug)]
    pub struct Dir(File);

    fn cname(name: &str) -> Result<CString> {
        CString::new(name).map_err(|_| FsError::BadName(name.to_string()))
    }

    fn errno_is(e: &io::Error, code: i32) -> bool {
        e.raw_os_error() == Some(code)
    }

    #[cfg(any(
        target_os = "macos",
        target_os = "ios",
        target_os = "freebsd",
        target_os = "openbsd",
        target_os = "netbsd"
    ))]
    unsafe fn reset_errno() {
        unsafe { *libc::__error() = 0 };
    }
    // Bionic has no `__errno_location`; its accessor is `__errno`.
    #[cfg(target_os = "android")]
    unsafe fn reset_errno() {
        unsafe { *libc::__errno() = 0 };
    }
    #[cfg(not(any(
        target_os = "macos",
        target_os = "ios",
        target_os = "freebsd",
        target_os = "openbsd",
        target_os = "netbsd",
        target_os = "android"
    )))]
    unsafe fn reset_errno() {
        unsafe { *libc::__errno_location() = 0 };
    }

    fn kind_of(mode: u32) -> EntryKind {
        match mode & libc::S_IFMT as u32 {
            m if m == libc::S_IFREG as u32 => EntryKind::File,
            m if m == libc::S_IFDIR as u32 => EntryKind::Dir,
            m if m == libc::S_IFLNK as u32 => EntryKind::Symlink,
            _ => EntryKind::Other,
        }
    }

    /// The kind a directory entry's `d_type` names, or `None` when the filesystem gave no type.
    pub(super) fn kind_from_dtype(d_type: u8) -> Option<EntryKind> {
        match d_type {
            libc::DT_REG => Some(EntryKind::File),
            libc::DT_DIR => Some(EntryKind::Dir),
            libc::DT_LNK => Some(EntryKind::Symlink),
            libc::DT_UNKNOWN => None,
            _ => Some(EntryKind::Other),
        }
    }

    fn fstat(file: &File) -> io::Result<libc::stat> {
        // SAFETY: zeroed stat is a valid out-parameter and fd is open.
        let mut st: libc::stat = unsafe { std::mem::zeroed() };
        if unsafe { libc::fstat(file.as_raw_fd(), &mut st) } != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(st)
    }

    fn open_dir_at(base: RawFd, name: &CStr, shown: &Path) -> Result<File> {
        // SAFETY: base is an open directory fd (or AT_FDCWD) and name is NUL-terminated.
        let fd = unsafe {
            libc::openat(
                base,
                name.as_ptr(),
                libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
            )
        };
        if fd < 0 {
            let e = io::Error::last_os_error();
            if errno_is(&e, libc::ELOOP) {
                return Err(FsError::Symlink(shown.to_path_buf()));
            }
            if errno_is(&e, libc::ENOTDIR) {
                // A symlink to a directory reports ENOTDIR with O_DIRECTORY|O_NOFOLLOW on some
                // kernels; distinguish it from a plain non-directory.
                // SAFETY: as above, with a valid out-parameter.
                let mut st: libc::stat = unsafe { std::mem::zeroed() };
                let rc = unsafe {
                    libc::fstatat(base, name.as_ptr(), &mut st, libc::AT_SYMLINK_NOFOLLOW)
                };
                if rc == 0 && kind_of(st.st_mode as u32) == EntryKind::Symlink {
                    return Err(FsError::Symlink(shown.to_path_buf()));
                }
                return Err(FsError::NotADirectory(shown.to_path_buf()));
            }
            return Err(FsError::io(shown, e));
        }
        // SAFETY: fd was just returned by openat and is owned here.
        Ok(unsafe { File::from_raw_fd(fd) })
    }

    /// `Ok(true)` when this call created the directory, `Ok(false)` when it already existed.
    ///
    /// macOS: a `parent` whose ACL would give the new directory an inheritable `allow` entry is refused
    /// before the `mkdirat` ([`FsError::UnsafeAcl`]), and a new directory that nevertheless
    /// carries an `allow` entry is (best effort) removed again, still empty, and refused. Nothing is
    /// repaired.
    fn mkdir_at(parent: &File, name: &CStr, shown: &Path) -> Result<bool> {
        let base = parent.as_raw_fd();
        crate::acl::guard_parent(parent, shown)?;
        // SAFETY: valid fd and C string.
        if unsafe { libc::mkdirat(base, name.as_ptr(), 0o700) } != 0 {
            let e = io::Error::last_os_error();
            if !errno_is(&e, libc::EEXIST) {
                return Err(FsError::io(shown, e));
            }
            return Ok(false);
        }
        #[cfg(feature = "testing")]
        super::testing::record_created(&name.to_string_lossy());
        if cfg!(target_os = "macos") {
            let checked = open_dir_at(base, name, shown)
                .and_then(|made| crate::acl::refuse_acl(&made, shown));
            if let Err(error) = checked {
                // SAFETY: valid fd and C string; AT_REMOVEDIR removes the empty directory just made.
                unsafe { libc::unlinkat(base, name.as_ptr(), libc::AT_REMOVEDIR) };
                return Err(error);
            }
        }
        Ok(true)
    }

    /// Flush a directory descriptor, reporting failure. The one place a directory is synced, so
    /// the `testing` seam sees every sync in order.
    fn sync_dir_file(dir: &File, policy: SyncPolicy) -> io::Result<Option<SyncLevel>> {
        #[cfg(feature = "testing")]
        if let Some(error) = super::testing::before_dir_sync(dir) {
            return Err(error);
        }
        super::flush(dir, policy).map(Some)
    }

    /// Makes the link to a directory this call has just created durable, by syncing `parent`.
    ///
    /// Called only when `mkdir_at` returned `Ok(true)` (the `mkdirat` succeeded; a directory that
    /// already existed, or that a racing creator made first, is `Ok(false)` and is neither synced
    /// nor looked at again). There is no record of earlier syncs and no walk over pre-existing
    /// directories. A failed sync is returned; the directory stays, and a later call finds it as
    /// an existing directory and does not sync it (the residual in the `atomic` module docs).
    fn publish_created(parent: &File, policy: SyncPolicy) -> io::Result<()> {
        sync_dir_file(parent, policy).map(|_| ())
    }

    /// `shared` skips the group/other-writable refusal (see `StateDir::open_shared`); the directory
    /// must still be a directory owned by the effective user.
    fn verify(file: &File, shown: &Path, shared: bool) -> Result<libc::stat> {
        let st = fstat(file).map_err(|e| FsError::io(shown, e))?;
        if kind_of(st.st_mode as u32) != EntryKind::Dir {
            return Err(FsError::NotADirectory(shown.to_path_buf()));
        }
        // SAFETY: geteuid has no preconditions.
        if st.st_uid != unsafe { libc::geteuid() } {
            return Err(FsError::NotOwned(shown.to_path_buf()));
        }
        if !shared && st.st_mode as u32 & 0o022 != 0 {
            return Err(FsError::TooPermissive(shown.to_path_buf()));
        }
        Ok(st)
    }

    impl Dir {
        fn fd(&self) -> RawFd {
            self.0.as_raw_fd()
        }

        pub fn pin(path: &Path, create: bool, options: &StateOptions, shared: bool) -> Result<Dir> {
            use std::path::Component;
            let root = CString::new("/").unwrap();
            let dot = CString::new(".").unwrap();
            let mut current = open_dir_at(
                libc::AT_FDCWD,
                if path.is_absolute() { &root } else { &dot },
                path,
            )?;
            let mut walked = std::path::PathBuf::new();
            for component in path.components() {
                let name = match component {
                    Component::RootDir => {
                        walked.push("/");
                        continue;
                    }
                    Component::CurDir => continue,
                    Component::ParentDir | Component::Prefix(_) => {
                        return Err(FsError::BadName(path.display().to_string()))
                    }
                    Component::Normal(n) => n,
                };
                walked.push(name);
                let c = CString::new(name.as_bytes())
                    .map_err(|_| FsError::BadName(path.display().to_string()))?;
                current = match open_dir_at(current.as_raw_fd(), &c, &walked) {
                    Err(FsError::Io { source, .. })
                        if create && errno_is(&source, libc::ENOENT) =>
                    {
                        let created = mkdir_at(&current, &c, &walked)?;
                        let next = open_dir_at(current.as_raw_fd(), &c, &walked)?;
                        // The new directory's entry lives in `current`. Publish it before
                        // descending, so a later durable write below cannot lose the link
                        // to the directory it went into. A failed flush stops here. Only a
                        // directory this call made is published; one that is already there
                        // (including one a racing creator made first) is left as it is.
                        if created {
                            publish_created(&current, options.sync).map_err(|source| {
                                FsError::DirSyncFailed {
                                    path: walked.clone(),
                                    source,
                                }
                            })?;
                        }
                        next
                    }
                    // Found, not made by this call: no sync, whoever made it and whenever.
                    Ok(next) => next,
                    Err(e) => return Err(e),
                };
            }
            let st = verify(&current, path, shared)?;
            // Defence in depth: the pinned inode must be the one the path names right now.
            match std::fs::symlink_metadata(path) {
                Ok(before)
                    if before.dev() == st.st_dev as u64 && before.ino() == st.st_ino as u64 => {}
                Ok(_) => return Err(FsError::IdentityChanged(path.to_path_buf())),
                Err(e) => return Err(FsError::io(path, e)),
            }
            Ok(Dir(current))
        }

        pub fn child(&self, name: &str, policy: SyncPolicy, shared: bool) -> Result<Dir> {
            let c = cname(name)?;
            let shown = Path::new(name);
            let mut created = false;
            let file = match open_dir_at(self.fd(), &c, shown) {
                Ok(f) => f,
                Err(FsError::Io { source, .. }) if errno_is(&source, libc::ENOENT) => {
                    created = mkdir_at(&self.0, &c, shown)?;
                    open_dir_at(self.fd(), &c, shown)?
                }
                Err(e) => return Err(e),
            };
            verify(&file, shown, shared)?;
            let child = Dir(file);
            // The entry lives in this directory; a child this call created is made durable like
            // a write. A child that already exists is returned as it is, with no sync.
            if created {
                publish_created(&self.0, policy).map_err(|source| FsError::DirSyncFailed {
                    path: shown.to_path_buf(),
                    source,
                })?;
            }
            Ok(child)
        }

        pub fn stat(&self, name: &str) -> Result<Option<EntryStat>> {
            let c = cname(name)?;
            // SAFETY: valid fd, C string, and zeroed out-parameter.
            let mut st: libc::stat = unsafe { std::mem::zeroed() };
            if unsafe { libc::fstatat(self.fd(), c.as_ptr(), &mut st, libc::AT_SYMLINK_NOFOLLOW) }
                == 0
            {
                return Ok(Some(EntryStat {
                    kind: kind_of(st.st_mode as u32),
                    size: st.st_size as u64,
                    dev: st.st_dev as u64,
                    ino: st.st_ino as u64,
                    mode: st.st_mode as u32 & 0o7777,
                    modified_unix_ms: (st.st_mtime as u64) * 1000
                        + (st.st_mtime_nsec as u64) / 1_000_000,
                }));
            }
            let e = io::Error::last_os_error();
            if errno_is(&e, libc::ENOENT) || errno_is(&e, libc::ENOTDIR) {
                Ok(None)
            } else {
                Err(FsError::io(name, e))
            }
        }

        /// Windows sharing and access flags need no Unix open flags. `O_NONBLOCK` keeps a planted
        /// FIFO or device from hanging the open; the
        /// caller (`StateDir::open_read`) refuses a non-regular file and returns the file to
        /// blocking mode.
        pub fn open_read_with(
            &self,
            name: &str,
            _options: &crate::handle::ReadOptions,
        ) -> Result<File> {
            let c = cname(name)?;
            // SAFETY: valid fd and C string.
            let fd = unsafe {
                libc::openat(
                    self.fd(),
                    c.as_ptr(),
                    libc::O_RDONLY | libc::O_NOFOLLOW | libc::O_CLOEXEC | libc::O_NONBLOCK,
                )
            };
            if fd < 0 {
                let e = io::Error::last_os_error();
                if errno_is(&e, libc::ELOOP) {
                    return Err(FsError::Symlink(name.into()));
                }
                return Err(FsError::io(name, e));
            }
            // SAFETY: fd just returned by openat.
            Ok(unsafe { File::from_raw_fd(fd) })
        }

        pub fn create_new(&self, name: &str, retain_name: bool) -> Result<File> {
            let c = cname(name)?;
            // macOS: no private file below a directory whose ACL would hand it an inheritable `allow` entry.
            crate::acl::guard_parent(&self.0, Path::new(name))?;
            // SAFETY: valid fd and C string; O_EXCL|O_NOFOLLOW means a planted symlink is never followed.
            let fd = unsafe {
                libc::openat(
                    self.fd(),
                    c.as_ptr(),
                    libc::O_WRONLY
                        | libc::O_CREAT
                        | libc::O_EXCL
                        | libc::O_NOFOLLOW
                        | libc::O_CLOEXEC,
                    0o600 as libc::c_uint,
                )
            };
            if fd < 0 {
                let e = io::Error::last_os_error();
                if errno_is(&e, libc::EEXIST) {
                    return Err(FsError::AlreadyExists(name.into()));
                }
                return Err(FsError::io(name, e));
            }
            // SAFETY: fd just returned by openat.
            let file = unsafe { File::from_raw_fd(fd) };
            #[cfg(feature = "testing")]
            if retain_name {
                super::testing::after_empty_create(&file)?;
            }
            // Temporary names may be removed while still empty. Direct permanent creation checks
            // this same handle in finish_read_open, once, without removing a visible final name.
            if !retain_name {
                if let Err(error) = crate::acl::refuse_acl(&file, Path::new(name)) {
                    drop(file);
                    // SAFETY: valid fd and C string.
                    unsafe { libc::unlinkat(self.fd(), c.as_ptr(), 0) };
                    return Err(error);
                }
            }
            Ok(file)
        }

        pub fn rename_replace(&self, from: &str, to: &str) -> Result<()> {
            let (cf, ct) = (cname(from)?, cname(to)?);
            // SAFETY: valid fds and C strings.
            if unsafe { libc::renameat(self.fd(), cf.as_ptr(), self.fd(), ct.as_ptr()) } != 0 {
                return Err(FsError::io(to, io::Error::last_os_error()));
            }
            Ok(())
        }

        /// No-replace publication: a hard link fails with EEXIST if `to` exists.
        pub fn link_new(&self, from: &str, to: &str) -> Result<()> {
            let (cf, ct) = (cname(from)?, cname(to)?);
            // SAFETY: valid fds and C strings.
            if unsafe { libc::linkat(self.fd(), cf.as_ptr(), self.fd(), ct.as_ptr(), 0) } != 0 {
                let e = io::Error::last_os_error();
                if errno_is(&e, libc::EEXIST) {
                    return Err(FsError::AlreadyExists(to.into()));
                }
                return Err(FsError::io(to, e));
            }
            Ok(())
        }

        pub fn unlink(&self, name: &str) -> Result<()> {
            let c = cname(name)?;
            // SAFETY: valid fd and C string.
            if unsafe { libc::unlinkat(self.fd(), c.as_ptr(), 0) } != 0 {
                return Err(FsError::io(name, io::Error::last_os_error()));
            }
            Ok(())
        }

        /// `unlinkat(AT_REMOVEDIR)`: removes an empty directory, and fails with `ENOTDIR` for a
        /// symlink or file at the name, so nothing but a real empty directory goes.
        pub fn remove_dir(&self, name: &str) -> Result<()> {
            let c = cname(name)?;
            // SAFETY: valid fd and C string.
            if unsafe { libc::unlinkat(self.fd(), c.as_ptr(), libc::AT_REMOVEDIR) } != 0 {
                return Err(FsError::io(name, io::Error::last_os_error()));
            }
            Ok(())
        }

        /// Unlink `name` only when `fstatat(AT_SYMLINK_NOFOLLOW)` says it is a symlink. POSIX has no
        /// unlink-if-symlink primitive, so a name swapped for another kind between the check and the
        /// `unlinkat` is unlinked as that kind (a file or symlink name; a directory is refused by
        /// `unlinkat` without `AT_REMOVEDIR`); the link's target is never touched either way.
        pub fn remove_link(&self, name: &str) -> Result<()> {
            let c = cname(name)?;
            // SAFETY: valid fd, C string, zeroed out-parameter.
            let mut st: libc::stat = unsafe { std::mem::zeroed() };
            if unsafe { libc::fstatat(self.fd(), c.as_ptr(), &mut st, libc::AT_SYMLINK_NOFOLLOW) }
                != 0
            {
                return Err(FsError::io(name, io::Error::last_os_error()));
            }
            if kind_of(st.st_mode as u32) != EntryKind::Symlink {
                return Err(FsError::io(
                    name,
                    io::Error::new(io::ErrorKind::InvalidInput, "the entry is not a symlink"),
                ));
            }
            self.unlink(name)
        }

        /// Remove `name` only after comparing the descriptor opened without following links to
        /// the name immediately before `unlinkat`. POSIX has no unlink-if-same-inode primitive,
        /// so an arbitrary mutator can still exchange the name after this comparison.
        pub fn unlink_regular(&self, name: &str) -> Result<bool> {
            let c = cname(name)?;
            // SAFETY: valid directory fd and NUL-terminated child name. O_NONBLOCK prevents a
            // planted FIFO from stalling cleanup before its type is rejected.
            let fd = unsafe {
                libc::openat(
                    self.fd(),
                    c.as_ptr(),
                    libc::O_RDONLY | libc::O_NONBLOCK | libc::O_NOFOLLOW | libc::O_CLOEXEC,
                )
            };
            if fd < 0 {
                let error = io::Error::last_os_error();
                return if errno_is(&error, libc::ENOENT) || errno_is(&error, libc::ELOOP) {
                    Ok(false)
                } else {
                    Err(FsError::io(name, error))
                };
            }
            // SAFETY: `fd` was just returned by openat and is owned by this File.
            let file = unsafe { File::from_raw_fd(fd) };
            let opened = fstat(&file).map_err(|error| FsError::io(name, error))?;
            if kind_of(opened.st_mode as u32) != EntryKind::File {
                return Ok(false);
            }
            // SAFETY: valid directory fd, child name, and stat out-parameter.
            let mut current: libc::stat = unsafe { std::mem::zeroed() };
            if unsafe {
                libc::fstatat(
                    self.fd(),
                    c.as_ptr(),
                    &mut current,
                    libc::AT_SYMLINK_NOFOLLOW,
                )
            } != 0
            {
                let error = io::Error::last_os_error();
                return if errno_is(&error, libc::ENOENT) {
                    Ok(false)
                } else {
                    Err(FsError::io(name, error))
                };
            }
            if kind_of(current.st_mode as u32) != EntryKind::File
                || opened.st_dev != current.st_dev
                || opened.st_ino != current.st_ino
            {
                return Ok(false);
            }
            // SAFETY: valid directory fd and child name. The comparison above narrows, but does
            // not eliminate, an unlink race with an arbitrary external path mutator.
            if unsafe { libc::unlinkat(self.fd(), c.as_ptr(), 0) } != 0 {
                let error = io::Error::last_os_error();
                return if errno_is(&error, libc::ENOENT) {
                    Ok(false)
                } else {
                    Err(FsError::io(name, error))
                };
            }
            Ok(true)
        }

        /// Flush this directory's entries. Unlike a file `fsync`, a failure is returned.
        pub fn sync(&self, policy: SyncPolicy) -> io::Result<Option<SyncLevel>> {
            sync_dir_file(&self.0, policy)
        }

        pub fn entries(&self, limit: usize) -> Result<Vec<DirEntry>> {
            // A fresh open file description of the pinned directory (`openat(dirfd, ".")`), not
            // a `dup`/`try_clone` of its descriptor: duplicated descriptors share one file
            // offset, so concurrent listings would consume each other's `getdents` position and
            // return partial results.
            let dot = CString::new(".").expect("no NUL in the string");
            let listing = open_dir_at(self.fd(), &dot, Path::new("."))?.into_raw_fd();
            // SAFETY: `listing` is a fresh owned fd; on success fdopendir takes ownership of it.
            let raw = unsafe { libc::fdopendir(listing) };
            if raw.is_null() {
                let e = io::Error::last_os_error();
                // SAFETY: fdopendir failed, so `listing` is still ours to close.
                unsafe { libc::close(listing) };
                return Err(FsError::io(".", e));
            }
            struct DirGuard(*mut libc::DIR);
            impl Drop for DirGuard {
                fn drop(&mut self) {
                    // SAFETY: pointer came from a successful fdopendir.
                    unsafe { libc::closedir(self.0) };
                }
            }
            // A new open file description starts at offset 0 and nothing else shares it.
            let guard = DirGuard(raw);
            let mut out = Vec::new();
            loop {
                // SAFETY: readdir signals end vs error through errno, which we clear first.
                unsafe { reset_errno() };
                let entry = unsafe { libc::readdir(guard.0) };
                if entry.is_null() {
                    let e = io::Error::last_os_error();
                    return if e.raw_os_error() == Some(0) {
                        Ok(out)
                    } else {
                        Err(FsError::io(".", e))
                    };
                }
                // SAFETY: d_name is a NUL-terminated array inside a live dirent.
                let raw_name = unsafe { CStr::from_ptr((*entry).d_name.as_ptr()) };
                let name = raw_name.to_string_lossy().into_owned();
                if name != "." && name != ".." {
                    if out.len() >= limit {
                        return Err(FsError::TooManyEntries(limit));
                    }
                    // SAFETY: d_type is a plain field of the live dirent.
                    let kind = match kind_from_dtype(unsafe { (*entry).d_type }) {
                        Some(kind) => kind,
                        None => {
                            #[cfg(feature = "testing")]
                            super::testing::count_fallback_stat();
                            // The filesystem reports no type: one descriptor-relative lstat.
                            // SAFETY: valid fd, NUL-terminated name, zeroed out-parameter.
                            let mut st: libc::stat = unsafe { std::mem::zeroed() };
                            let rc = unsafe {
                                libc::fstatat(
                                    self.fd(),
                                    raw_name.as_ptr(),
                                    &mut st,
                                    libc::AT_SYMLINK_NOFOLLOW,
                                )
                            };
                            if rc != 0 {
                                let e = io::Error::last_os_error();
                                if errno_is(&e, libc::ENOENT) {
                                    continue; // removed between readdir and fstatat
                                }
                                return Err(FsError::io(&name, e));
                            }
                            kind_of(st.st_mode as u32)
                        }
                    };
                    out.push(DirEntry { name, kind });
                }
            }
        }
    }
}

#[cfg(windows)]
#[path = "state/windows.rs"]
mod sys;

#[cfg(not(any(unix, windows)))]
mod sys {
    use super::{DirEntry, EntryKind, EntryStat, StateOptions};
    use crate::atomic::{SyncLevel, SyncPolicy};
    use crate::error::{FsError, Result};
    use std::fs::{self, File, OpenOptions};
    use std::path::{Path, PathBuf};

    #[derive(Debug)]
    pub struct Dir(PathBuf);

    fn is_link(meta: &fs::Metadata) -> bool {
        if meta.file_type().is_symlink() {
            return true;
        }
        #[cfg(windows)]
        {
            use std::os::windows::fs::MetadataExt;
            if meta.file_attributes() & 0x400 != 0 {
                return true; // FILE_ATTRIBUTE_REPARSE_POINT
            }
        }
        false
    }

    fn reject_links(path: &Path) -> Result<()> {
        for ancestor in path.ancestors() {
            match fs::symlink_metadata(ancestor) {
                Ok(m) if is_link(&m) => return Err(FsError::Symlink(path.to_path_buf())),
                Ok(_) | Err(_) => {}
            }
        }
        Ok(())
    }

    impl Dir {
        pub fn pin(
            path: &Path,
            create: bool,
            _options: &StateOptions,
            _shared: bool,
        ) -> Result<Dir> {
            reject_links(path)?;
            if create {
                fs::create_dir_all(path).map_err(|e| FsError::io(path, e))?;
            }
            reject_links(path)?;
            if !fs::metadata(path)
                .map_err(|e| FsError::io(path, e))?
                .is_dir()
            {
                return Err(FsError::NotADirectory(path.to_path_buf()));
            }
            Ok(Dir(path.to_path_buf()))
        }
        pub fn child(&self, name: &str, _policy: SyncPolicy, shared: bool) -> Result<Dir> {
            let p = self.0.join(name);
            Dir::pin(&p, true, &StateOptions::default(), shared)
        }
        pub fn stat(&self, name: &str) -> Result<Option<EntryStat>> {
            let p = self.0.join(name);
            match fs::symlink_metadata(&p) {
                Ok(m) => Ok(Some(EntryStat {
                    kind: if is_link(&m) {
                        EntryKind::Symlink
                    } else if m.is_dir() {
                        EntryKind::Dir
                    } else if m.is_file() {
                        EntryKind::File
                    } else {
                        EntryKind::Other
                    },
                    size: m.len(),
                    dev: 0,
                    ino: 0,
                    mode: 0,
                    modified_unix_ms: m
                        .modified()
                        .ok()
                        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                        .map(|d| d.as_millis() as u64)
                        .unwrap_or(0),
                })),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(e) => Err(FsError::io(p, e)),
            }
        }
        pub fn open_read_with(
            &self,
            name: &str,
            _options: &crate::handle::ReadOptions,
        ) -> Result<File> {
            let p = self.0.join(name);
            if let Ok(m) = fs::symlink_metadata(&p) {
                if is_link(&m) {
                    return Err(FsError::Symlink(p));
                }
            }
            File::open(&p).map_err(|e| FsError::io(p, e))
        }
        pub fn create_new(&self, name: &str, _retain_name: bool) -> Result<File> {
            let p = self.0.join(name);
            let f = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&p)
                .map_err(|e| {
                    if e.kind() == std::io::ErrorKind::AlreadyExists {
                        FsError::AlreadyExists(p.clone())
                    } else {
                        FsError::io(&p, e)
                    }
                })?;
            crate::private::restrict_owner_only(&p)?;
            Ok(f)
        }
        pub fn rename_replace(&self, from: &str, to: &str) -> Result<()> {
            fs::rename(self.0.join(from), self.0.join(to))
                .map_err(|e| FsError::io(self.0.join(to), e))
        }
        pub fn link_new(&self, from: &str, to: &str) -> Result<()> {
            fs::hard_link(self.0.join(from), self.0.join(to)).map_err(|e| {
                if e.kind() == std::io::ErrorKind::AlreadyExists {
                    FsError::AlreadyExists(self.0.join(to))
                } else {
                    FsError::io(self.0.join(to), e)
                }
            })
        }
        pub fn unlink(&self, name: &str) -> Result<()> {
            fs::remove_file(self.0.join(name)).map_err(|e| FsError::io(self.0.join(name), e))
        }
        pub fn remove_dir(&self, name: &str) -> Result<()> {
            let p = self.0.join(name);
            match fs::symlink_metadata(&p) {
                Ok(m) if is_link(&m) => Err(FsError::Symlink(p)),
                Ok(_) => fs::remove_dir(&p).map_err(|e| FsError::io(p, e)),
                Err(e) => Err(FsError::io(p, e)),
            }
        }
        pub fn remove_link(&self, name: &str) -> Result<()> {
            let p = self.0.join(name);
            match fs::symlink_metadata(&p) {
                Ok(m) if is_link(&m) => fs::remove_file(&p)
                    .or_else(|_| fs::remove_dir(&p))
                    .map_err(|e| FsError::io(p, e)),
                Ok(_) => Err(FsError::io(
                    p,
                    std::io::Error::new(std::io::ErrorKind::InvalidInput, "not a link"),
                )),
                Err(e) => Err(FsError::io(p, e)),
            }
        }
        pub fn unlink_regular(&self, name: &str) -> Result<bool> {
            let path = self.0.join(name);
            match fs::symlink_metadata(&path) {
                Ok(meta) if meta.is_file() => match fs::remove_file(&path) {
                    Ok(()) => Ok(true),
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
                    Err(error) => Err(FsError::io(path, error)),
                },
                Ok(_) | Err(_) => Ok(false),
            }
        }
        pub fn sync(&self, _policy: SyncPolicy) -> std::io::Result<Option<SyncLevel>> {
            Ok(None)
        }
        pub fn entries(&self, limit: usize) -> Result<Vec<DirEntry>> {
            let mut out = Vec::new();
            for entry in fs::read_dir(&self.0).map_err(|e| FsError::io(&self.0, e))? {
                let entry = entry.map_err(|e| FsError::io(&self.0, e))?;
                if out.len() >= limit {
                    return Err(FsError::TooManyEntries(limit));
                }
                let kind = match entry.file_type() {
                    Ok(t) if t.is_symlink() => EntryKind::Symlink,
                    Ok(t) if t.is_dir() => EntryKind::Dir,
                    Ok(t) if t.is_file() => EntryKind::File,
                    _ => EntryKind::Other,
                };
                out.push(DirEntry {
                    name: entry.file_name().to_string_lossy().into_owned(),
                    kind,
                });
            }
            Ok(out)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn windows_attributes_map_to_kinds() {
        assert_eq!(kind_from_attributes(0x20), EntryKind::File); // ARCHIVE
        assert_eq!(kind_from_attributes(0x10), EntryKind::Dir);
        assert_eq!(kind_from_attributes(0x400), EntryKind::Symlink);
        // A directory symlink/junction is both: the reparse point wins.
        assert_eq!(kind_from_attributes(0x10 | 0x400), EntryKind::Symlink);
        assert_eq!(kind_from_attributes(0x80 | 0x2), EntryKind::File); // NORMAL | HIDDEN
    }

    #[cfg(unix)]
    #[test]
    fn dtype_maps_to_kinds_and_unknown_needs_a_stat() {
        use super::sys::kind_from_dtype;
        assert_eq!(kind_from_dtype(libc::DT_REG), Some(EntryKind::File));
        assert_eq!(kind_from_dtype(libc::DT_DIR), Some(EntryKind::Dir));
        assert_eq!(kind_from_dtype(libc::DT_LNK), Some(EntryKind::Symlink));
        for other in [libc::DT_FIFO, libc::DT_SOCK, libc::DT_CHR, libc::DT_BLK] {
            assert_eq!(kind_from_dtype(other), Some(EntryKind::Other));
        }
        assert_eq!(kind_from_dtype(libc::DT_UNKNOWN), None);
    }

    #[test]
    fn temp_prefix_is_bounded_and_cut_on_a_char_boundary() {
        assert_eq!(temp_prefix("abc"), "abc");
        assert_eq!(temp_prefix(&"a".repeat(255)).len(), 64);
        // 63 ASCII bytes then a 2-byte char straddling the 64-byte limit.
        let name = format!("{}\u{e9}tail", "a".repeat(63));
        assert_eq!(temp_prefix(&name).len(), 63);
        // The longest temp name still fits the platform component limit.
        let temp = format!(
            ".{}{TEMP_MARKER}{}-{}-{}",
            "a".repeat(64),
            u32::MAX,
            u64::MAX,
            31
        );
        assert!(temp.len() <= PLATFORM_NAME_LIMIT, "{}", temp.len());
    }

    #[test]
    fn name_checks_use_the_limit_they_are_given() {
        let long = "n".repeat(230);
        assert!(check_name(&long, PLATFORM_NAME_LIMIT).is_ok());
        #[cfg(not(windows))]
        assert!(check_name(&long, DEFAULT_WRITE_NAME_LEN).is_err());
        assert!(check_name(&"n".repeat(256), PLATFORM_NAME_LIMIT).is_err());
        assert!(check_name("a/b", PLATFORM_NAME_LIMIT).is_err());
    }
}

/// `open_shared`, `open_read`, `remove_dir` and `remove_link` (rightkit#613).
#[cfg(test)]
mod handle_policy_tests {
    use super::*;
    use crate::handle::ReadOptions;

    fn tmp() -> (tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().canonicalize().unwrap();
        (dir, path)
    }

    #[test]
    fn open_read_returns_a_regular_file_handle() {
        let (_g, root) = tmp();
        let state = StateDir::create(&root.join("s")).unwrap();
        state.write("f", b"bytes").unwrap();
        let mut file = state.open_read("f", &ReadOptions::new()).unwrap();
        let mut text = String::new();
        std::io::Read::read_to_string(&mut file, &mut text).unwrap();
        assert_eq!(text, "bytes");
        assert!(state
            .open_read("absent", &ReadOptions::new())
            .unwrap_err()
            .is_not_found());
        for bad in ["", "..", "a/b", "a\0b"] {
            assert!(matches!(
                state.open_read(bad, &ReadOptions::new()),
                Err(FsError::BadName(_))
            ));
        }
    }

    #[test]
    fn open_read_refuses_a_directory_and_can_require_a_single_link() {
        let (_g, root) = tmp();
        let state = StateDir::create(&root.join("s")).unwrap();
        state.child("sub").unwrap();
        assert!(matches!(
            state.open_read("sub", &ReadOptions::new()),
            Err(FsError::NotAFile(_) | FsError::Io { .. })
        ));
        state.write("f", b"x").unwrap();
        let strict = ReadOptions::new().require_single_link(true);
        assert!(state.open_read("f", &strict).is_ok());
        std::fs::hard_link(root.join("s/f"), root.join("s/alias")).unwrap();
        assert!(matches!(
            state.open_read("f", &strict),
            Err(FsError::HardLinked(_))
        ));
        assert!(state.open_read("f", &ReadOptions::new()).is_ok());
    }

    #[test]
    fn stat_reports_an_identity_that_tells_two_files_apart_and_a_hard_link_together() {
        let (_g, root) = tmp();
        let state = StateDir::create(&root.join("s")).unwrap();
        state.write("a", b"1").unwrap();
        state.write("b", b"2").unwrap();
        std::fs::hard_link(root.join("s/a"), root.join("s/a2")).unwrap();
        let (a, b, a2) = (
            state.stat("a").unwrap().unwrap(),
            state.stat("b").unwrap().unwrap(),
            state.stat("a2").unwrap().unwrap(),
        );
        assert!(a.ino != 0 && b.ino != 0, "an identity was reported");
        assert_ne!((a.dev, a.ino), (b.dev, b.ino));
        assert_eq!((a.dev, a.ino), (a2.dev, a2.ino));
    }

    #[test]
    fn remove_dir_removes_only_an_empty_real_directory() {
        let (_g, root) = tmp();
        let state = StateDir::create(&root.join("s")).unwrap();
        state.child("empty").unwrap();
        assert!(state.remove_dir("empty").unwrap());
        assert!(!state.exists("empty").unwrap());
        assert!(!state.remove_dir("empty").unwrap(), "missing is Ok(false)");
        // A directory with content stays, with its content.
        let full = state.child("full").unwrap();
        full.write("keep", b"x").unwrap();
        assert!(state.remove_dir("full").is_err());
        assert_eq!(full.read("keep", 10).unwrap(), b"x");
        // A file is not a directory.
        state.write("file", b"x").unwrap();
        assert!(state.remove_dir("file").is_err());
        assert!(state.exists("file").unwrap());
        assert!(matches!(state.remove_dir("../x"), Err(FsError::BadName(_))));
    }

    #[test]
    fn remove_link_refuses_content_that_is_not_a_link() {
        let (_g, root) = tmp();
        let state = StateDir::create(&root.join("s")).unwrap();
        state.write("file", b"x").unwrap();
        state.child("dir").unwrap();
        assert_eq!(
            state.remove_link("file").unwrap_err().kind(),
            Some(std::io::ErrorKind::InvalidInput)
        );
        assert_eq!(
            state.remove_link("dir").unwrap_err().kind(),
            Some(std::io::ErrorKind::InvalidInput)
        );
        assert!(state.exists("file").unwrap() && state.exists("dir").unwrap());
        assert!(!state.remove_link("absent").unwrap());
    }

    #[cfg(unix)]
    mod unix {
        use super::*;
        use std::os::unix::fs::{symlink, PermissionsExt};

        #[test]
        fn open_shared_accepts_a_group_writable_directory_that_open_refuses() {
            let (_g, root) = tmp();
            let dir = root.join("shared");
            std::fs::create_dir(&dir).unwrap();
            std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o775)).unwrap();
            assert!(matches!(
                StateDir::open(&dir),
                Err(FsError::TooPermissive(_))
            ));
            let state = StateDir::open_shared(&dir).unwrap();
            state.write("f", b"x").unwrap();
            assert_eq!(state.read("f", 10).unwrap(), b"x");
        }

        #[test]
        fn open_shared_still_refuses_a_symlink_and_a_file() {
            let (_g, root) = tmp();
            let dir = root.join("real");
            std::fs::create_dir(&dir).unwrap();
            symlink(&dir, root.join("link")).unwrap();
            assert!(matches!(
                StateDir::open_shared(&root.join("link")),
                Err(FsError::Symlink(_))
            ));
            std::fs::write(root.join("file"), b"x").unwrap();
            assert!(matches!(
                StateDir::open_shared(&root.join("file")),
                Err(FsError::NotADirectory(_))
            ));
        }

        #[test]
        fn a_child_of_a_shared_directory_is_shared_and_of_a_private_one_is_not() {
            let (_g, root) = tmp();
            let dir = root.join("shared");
            std::fs::create_dir(&dir).unwrap();
            std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o775)).unwrap();
            let kid = dir.join("kid");
            std::fs::create_dir(&kid).unwrap();
            std::fs::set_permissions(&kid, std::fs::Permissions::from_mode(0o777)).unwrap();
            assert!(StateDir::open_shared(&dir).unwrap().child("kid").is_ok());
            let private = root.join("private");
            std::fs::create_dir(&private).unwrap();
            std::fs::set_permissions(&private, std::fs::Permissions::from_mode(0o700)).unwrap();
            let pk = private.join("kid");
            std::fs::create_dir(&pk).unwrap();
            std::fs::set_permissions(&pk, std::fs::Permissions::from_mode(0o777)).unwrap();
            assert!(matches!(
                StateDir::open(&private).unwrap().child("kid"),
                Err(FsError::TooPermissive(_))
            ));
        }

        #[test]
        fn open_read_refuses_a_symlink_and_never_waits_on_a_fifo() {
            use std::ffi::CString;
            use std::os::unix::ffi::OsStrExt;
            let (_g, root) = tmp();
            let state = StateDir::create(&root.join("s")).unwrap();
            state.write("real", b"x").unwrap();
            symlink(root.join("s/real"), root.join("s/link")).unwrap();
            assert!(matches!(
                state.open_read("link", &ReadOptions::new()),
                Err(FsError::Symlink(_))
            ));
            let fifo = root.join("s/pipe");
            let c = CString::new(fifo.as_os_str().as_bytes()).unwrap();
            // SAFETY: valid NUL-terminated path.
            assert_eq!(unsafe { libc::mkfifo(c.as_ptr(), 0o600) }, 0);
            assert!(matches!(
                state.open_read("pipe", &ReadOptions::new()),
                Err(FsError::NotAFile(_))
            ));
            assert!(matches!(state.read("pipe", 10), Err(FsError::NotAFile(_))));
        }

        #[test]
        fn remove_link_removes_the_link_and_never_the_target() {
            let (_g, root) = tmp();
            let state = StateDir::create(&root.join("s")).unwrap();
            let outside = root.join("outside");
            std::fs::create_dir(&outside).unwrap();
            std::fs::write(outside.join("keep"), b"keep").unwrap();
            symlink(&outside, root.join("s/dirlink")).unwrap();
            symlink(root.join("nowhere"), root.join("s/dangling")).unwrap();
            assert!(state.remove_link("dirlink").unwrap());
            assert!(state.remove_link("dangling").unwrap());
            assert!(!state.exists("dirlink").unwrap());
            assert_eq!(std::fs::read(outside.join("keep")).unwrap(), b"keep");
            // remove_dir refuses a symlink to a directory and leaves it.
            symlink(&outside, root.join("s/again")).unwrap();
            assert!(state.remove_dir("again").is_err());
            assert!(state.exists("again").unwrap());
        }
    }

    #[cfg(windows)]
    mod windows {
        use super::*;

        /// A junction needs no privilege: `mklink /J`.
        fn junction(link: &Path, target: &Path) -> bool {
            // cmd.exe does not take a verbatim `\\?\` path.
            let plain = |p: &Path| crate::plain::plain_path(p.to_path_buf());
            std::process::Command::new("cmd")
                .args(["/C", "mklink", "/J"])
                .arg(plain(link))
                .arg(plain(target))
                .output()
                .map(|o| o.status.success())
                .unwrap_or(false)
        }

        #[test]
        fn a_junction_is_removed_by_remove_link_and_its_target_survives() {
            let (_g, root) = tmp();
            let state = StateDir::create(&root.join("s")).unwrap();
            let outside = root.join("outside");
            std::fs::create_dir(&outside).unwrap();
            std::fs::write(outside.join("keep"), b"keep").unwrap();
            if !junction(&root.join("s").join("j"), &outside) {
                return; // cmd.exe unavailable in this environment
            }
            // The junction is refused everywhere a directory or file is expected.
            assert!(matches!(state.remove_dir("j"), Err(FsError::Symlink(_))));
            assert!(matches!(state.child("j"), Err(FsError::Symlink(_))));
            assert!(state.remove_link("j").unwrap());
            assert!(std::fs::symlink_metadata(root.join("s").join("j")).is_err());
            assert_eq!(std::fs::read(outside.join("keep")).unwrap(), b"keep");
        }

        #[test]
        fn read_only_sharing_blocks_a_writer_while_the_handle_is_open() {
            let (_g, root) = tmp();
            let state = StateDir::create(&root.join("s")).unwrap();
            state.write("f", b"x").unwrap();
            let shared = ReadOptions::new().share_read_only(true);
            let reader = state.open_read("f", &shared).unwrap();
            let writer = std::fs::OpenOptions::new()
                .write(true)
                .open(root.join("s").join("f"));
            assert_eq!(writer.unwrap_err().raw_os_error(), Some(32));
            drop(reader);
            assert!(std::fs::OpenOptions::new()
                .write(true)
                .open(root.join("s").join("f"))
                .is_ok());
        }
    }
}

//! Native bindings match winternl.h/winbase.h. No path is retained for operations.
use super::{DirEntry, EntryKind, EntryStat, StateOptions};
use crate::atomic::{SyncLevel, SyncPolicy};
use crate::error::{FsError, Result};
use crate::private::{discard_unverified_owner_only, verify_owner_only_handle, SecurityDescriptor};
use std::ffi::{c_void, OsStr};
use std::fs::File;
use std::io;
use std::mem::{offset_of, size_of};
use std::os::windows::ffi::OsStrExt;
use std::os::windows::io::{AsRawHandle, FromRawHandle};
use std::path::{Component, Path, PathBuf, Prefix};
use std::ptr::{null, null_mut};
use std::sync::Mutex;

type Handle = *mut c_void;
const READ_ATTRIBUTES: u32 = 0x80;
const READ_CONTROL: u32 = 0x0002_0000;
const SYNCHRONIZE: u32 = 0x0010_0000;
const DELETE: u32 = 0x0001_0000;
// Files are opened without FILE_SHARE_DELETE on purpose: removal and publication go through
// handle-based disposition and rename, so nobody needs delete sharing on a file.
const SHARE_READ_WRITE: u32 = 3;
const FILE_SHARE_READ: u32 = 1;
// Directories default to the same, so a pinned directory (and every ancestor) cannot be renamed
// or deleted under the pin, and `StateDir::path()` stays true. `allow_rename_while_open`
// switches directories to this.
const SHARE_READ_WRITE_DELETE: u32 = 7;
// FILE_WRITE_THROUGH on the handle that creates a directory, renames or deletes: the same
// mechanism MOVEFILE_WRITE_THROUGH relies on. There is no directory flush on Windows (see
// `Dir::sync`).
const FILE_WRITE_THROUGH: u32 = 0x2;
const FILE_OPEN: u32 = 1;
const FILE_CREATE: u32 = 2;
const FILE_OPEN_IF: u32 = 3;
const DIRECTORY_FILE: u32 = 1;
const NON_DIRECTORY_FILE: u32 = 0x40;
const OPEN_REPARSE_POINT: u32 = 0x0020_0000;
const SYNCHRONOUS_IO_NONALERT: u32 = 0x20;
const ATTRIBUTE_DIRECTORY: u32 = 0x10;
const ATTRIBUTE_REPARSE_POINT: u32 = 0x400;
const FILE_ATTRIBUTE_TAG_INFO: i32 = 9;
const IO_REPARSE_TAG_SYMLINK: u32 = 0xA000_000C;
const IO_REPARSE_TAG_MOUNT_POINT: u32 = 0xA000_0003;
const FILE_DISPOSITION_INFO: i32 = 4;
const FILE_RENAME_INFORMATION: i32 = 10;
const FILE_ID_BOTH_DIRECTORY_INFO: i32 = 10;
const FILE_ID_BOTH_DIRECTORY_RESTART_INFO: i32 = 11;

#[repr(C)]
struct UnicodeString {
    length: u16,
    maximum_length: u16,
    buffer: *mut u16,
}

#[repr(C)]
struct ObjectAttributes {
    length: u32,
    root_directory: Handle,
    object_name: *mut UnicodeString,
    attributes: u32,
    security_descriptor: *mut c_void,
    security_quality_of_service: *mut c_void,
}

#[repr(C)]
struct IoStatusBlock {
    status: usize, // NTSTATUS / pointer union.
    information: usize,
}

#[repr(C)]
struct AttributeTagInfo {
    attributes: u32,
    tag: u32,
}

#[repr(C)]
#[derive(PartialEq, Eq)]
struct FileIdInfo {
    volume: u64,
    id: [u8; 16],
}

#[repr(C)]
struct RenameInfo {
    replace_if_exists: u8,
    root_directory: Handle,
    file_name_length: u32,
    file_name: [u16; 1],
}

#[repr(C)]
#[derive(Clone, Copy)]
struct DirectoryInfo {
    next_entry_offset: u32,
    file_index: u32,
    creation_time: i64,
    last_access_time: i64,
    last_write_time: i64,
    change_time: i64,
    end_of_file: i64,
    allocation_size: i64,
    attributes: u32,
    file_name_length: u32,
    ea_size: u32,
    short_name_length: i8,
    short_name: [u16; 12],
    file_id: i64,
    file_name: [u16; 1],
}

#[link(name = "ntdll")]
unsafe extern "system" {
    fn NtCreateFile(
        file: *mut Handle,
        access: u32,
        attributes: *mut ObjectAttributes,
        status: *mut IoStatusBlock,
        allocation: *const i64,
        file_attributes: u32,
        share: u32,
        disposition: u32,
        options: u32,
        ea: *const c_void,
        ea_length: u32,
    ) -> i32;
    fn NtSetInformationFile(
        file: Handle,
        status: *mut IoStatusBlock,
        info: *const c_void,
        size: u32,
        class: i32,
    ) -> i32;
    fn RtlNtStatusToDosError(status: i32) -> u32;
}

#[link(name = "kernel32")]
unsafe extern "system" {
    fn CreateFileW(
        name: *const u16,
        access: u32,
        share: u32,
        security: *const c_void,
        disposition: u32,
        flags: u32,
        template: Handle,
    ) -> Handle;
    fn GetFileInformationByHandleEx(file: Handle, class: i32, info: *mut c_void, size: u32) -> i32;
    fn SetFileInformationByHandle(file: Handle, class: i32, info: *const c_void, size: u32) -> i32;
    // Only the tests read security descriptors back and free them.
    #[cfg_attr(not(test), allow(dead_code))]
    fn LocalFree(memory: *mut c_void) -> *mut c_void;
}

/// What a pinned directory remembers from its [`StateOptions`], inherited by children.
#[derive(Clone, Copy, Debug)]
struct Config {
    /// Share mode for directory handles (`SHARE_READ_WRITE` or `SHARE_READ_WRITE_DELETE`).
    directory_share: u32,
    /// Create without an explicit security descriptor, so the parent's ACL is inherited.
    inherit_acl: bool,
}

impl Config {
    fn from_options(options: &StateOptions) -> Self {
        Self {
            directory_share: if options.allow_rename_while_open {
                SHARE_READ_WRITE_DELETE
            } else {
                SHARE_READ_WRITE
            },
            inherit_acl: options.inherit_acl(),
        }
    }
}

#[derive(Debug)]
pub struct Dir {
    file: File,
    enumeration: Mutex<()>,
    config: Config,
}

fn raw_attributes(file: &File, shown: &Path) -> Result<AttributeTagInfo> {
    let mut info = AttributeTagInfo {
        attributes: 0,
        tag: 0,
    };
    // SAFETY: open handle and correctly sized writable structure.
    if unsafe {
        GetFileInformationByHandleEx(
            file.as_raw_handle(),
            FILE_ATTRIBUTE_TAG_INFO,
            (&mut info as *mut AttributeTagInfo).cast(),
            size_of::<AttributeTagInfo>() as u32,
        )
    } == 0
    {
        return Err(FsError::io(shown, io::Error::last_os_error()));
    }
    Ok(info)
}

/// The attributes of an opened child, refusing any reparse point.
fn attributes(file: &File, shown: &Path) -> Result<u32> {
    let info = raw_attributes(file, shown)?;
    if info.attributes & ATTRIBUTE_REPARSE_POINT != 0 {
        return Err(FsError::Symlink(shown.to_path_buf()));
    }
    Ok(info.attributes)
}

/// The attributes of an opened child that must be a symlink or a junction (a mount point): the one
/// kind of reparse point [`Dir::remove_link`] may delete. Anything else is refused.
fn link_attributes(file: &File, shown: &Path) -> Result<u32> {
    let info = raw_attributes(file, shown)?;
    let is_link = info.attributes & ATTRIBUTE_REPARSE_POINT != 0
        && matches!(
            info.tag,
            IO_REPARSE_TAG_SYMLINK | IO_REPARSE_TAG_MOUNT_POINT
        );
    if !is_link {
        return Err(FsError::io(
            shown,
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "the entry is not a symlink or junction",
            ),
        ));
    }
    Ok(info.attributes)
}

/// What an opened child must be: an ordinary entry, or the reparse point itself.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Check {
    /// Refuse a reparse point (every ordinary child open).
    NoReparse,
    /// Require a symlink or junction and keep it open as the link itself (link removal).
    ReparseLink,
}

/// Mark an open child (opened with `DELETE`) for deletion through that handle.
fn mark_delete(file: &File, name: &str) -> Result<()> {
    let delete: u8 = 1; // FILE_DISPOSITION_INFO.DeleteFile is BOOLEAN, not BOOL.
                        // SAFETY: live child handle, opened without reparse traversal or delete sharing.
    if unsafe {
        SetFileInformationByHandle(
            file.as_raw_handle(),
            FILE_DISPOSITION_INFO,
            (&delete as *const u8).cast(),
            1,
        )
    } == 0
    {
        return Err(FsError::io(name, io::Error::last_os_error()));
    }
    Ok(())
}

pub(super) fn valid_component(name: &str, limit: usize) -> bool {
    !name.is_empty()
        && name != "."
        && name != ".."
        && !name.ends_with(['.', ' '])
        && !name
            .chars()
            .any(|c| c < ' ' || matches!(c, '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|'))
        && name.encode_utf16().count() <= limit
}

fn component(name: &OsStr) -> Result<Vec<u16>> {
    let shown = name.to_string_lossy();
    // Lossy names are refused rather than addressing a different entry.
    let text = name
        .to_str()
        .ok_or_else(|| FsError::BadName(shown.into_owned()))?;
    if !valid_component(text, super::PLATFORM_NAME_LIMIT) {
        return Err(FsError::BadName(text.to_string()));
    }
    Ok(name.encode_wide().collect())
}

impl Dir {
    fn open_path(path: &Path, config: Config, share: u32) -> Result<Self> {
        let wide: Vec<u16> = path.as_os_str().encode_wide().chain(Some(0)).collect();
        if wide[..wide.len() - 1].contains(&0) {
            return Err(FsError::BadName(path.display().to_string()));
        }
        // SAFETY: NUL-terminated path, no security/template pointers. OPEN_REPARSE_POINT
        // opens the leaf itself; identity is compared with the component walk before use.
        let raw = unsafe {
            CreateFileW(
                wide.as_ptr(),
                1 | READ_ATTRIBUTES | SYNCHRONIZE,
                share,
                null(),
                3,
                0x0200_0000 | 0x0020_0000,
                null_mut(),
            ) // FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT
        };
        if raw as isize == -1 || raw.is_null() {
            return Err(FsError::io(path, io::Error::last_os_error()));
        }
        // SAFETY: CreateFileW returned a fresh owned handle.
        Self::verified(unsafe { File::from_raw_handle(raw) }, path, config)
    }

    fn identity(&self, shown: &Path) -> Result<FileIdInfo> {
        let mut id = FileIdInfo {
            volume: 0,
            id: [0; 16],
        };
        // SAFETY: live directory handle and a correctly sized FileIdInfo out-parameter.
        if unsafe {
            GetFileInformationByHandleEx(
                self.file.as_raw_handle(),
                18,
                (&mut id as *mut FileIdInfo).cast(),
                size_of::<FileIdInfo>() as u32,
            )
        } == 0
        {
            return Err(FsError::io(shown, io::Error::last_os_error()));
        }
        Ok(id)
    }

    fn verified(file: File, shown: &Path, config: Config) -> Result<Self> {
        if attributes(&file, shown)? & ATTRIBUTE_DIRECTORY == 0 {
            return Err(FsError::NotADirectory(shown.to_path_buf()));
        }
        Ok(Self {
            file,
            enumeration: Mutex::new(()),
            config,
        })
    }

    fn open_at(
        &self,
        entry_name: &OsStr,
        access: u32,
        disposition: u32,
        options: u32,
    ) -> Result<File> {
        self.open_at_with(
            entry_name,
            access,
            disposition,
            options,
            SHARE_READ_WRITE,
            Check::NoReparse,
        )
    }

    /// [`open_at`](Self::open_at) with the file share mode (directories always use the configured
    /// directory share) and what the opened child must be.
    fn open_at_with(
        &self,
        entry_name: &OsStr,
        access: u32,
        disposition: u32,
        options: u32,
        share_file: u32,
        check: Check,
    ) -> Result<File> {
        self.open_at_with_retention(
            entry_name,
            access,
            disposition,
            options,
            share_file,
            check,
            false,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn open_at_with_retention(
        &self,
        entry_name: &OsStr,
        access: u32,
        disposition: u32,
        options: u32,
        share_file: u32,
        check: Check,
        retain_name: bool,
    ) -> Result<File> {
        let shown = Path::new(entry_name);
        let mut wide = component(entry_name)?;
        let len = u16::try_from(wide.len() * 2)
            .map_err(|_| FsError::BadName(shown.display().to_string()))?;
        let mut name = UnicodeString {
            length: len,
            maximum_length: len,
            buffer: wide.as_mut_ptr(),
        };
        let directory = options & DIRECTORY_FILE != 0;
        // `FILE_OPEN_IF` cannot request verification/cleanup rights from an already-existing
        // ancestor. Create privately first; an actual collision reopens with original minimal
        // rights. A collision followed by disappearance is an error, never a broad retry.
        let create_only = disposition == FILE_OPEN_IF && !self.config.inherit_acl;
        let native_disposition = if create_only {
            FILE_CREATE
        } else {
            disposition
        };
        let security = if native_disposition != FILE_OPEN && !self.config.inherit_acl {
            Some(SecurityDescriptor::owner_only(shown, directory)?)
        } else {
            None
        };
        // A temporary creation needs DELETE for failed-verification cleanup. A permanent lock
        // must keep its name on error and omit DELETE: other StateDir readers intentionally do
        // not share deletion, and must be able to open while the creator retains its handle.
        let creation_security_access = if security.is_some() {
            READ_CONTROL | if retain_name { 0 } else { DELETE }
        } else {
            0
        };
        let mut object = ObjectAttributes {
            length: size_of::<ObjectAttributes>() as u32,
            root_directory: self.file.as_raw_handle(),
            object_name: &mut name,
            attributes: 0x40, // OBJ_CASE_INSENSITIVE, never OBJ_INHERIT.
            security_descriptor: security.as_ref().map_or(null_mut(), |s| s.0),
            security_quality_of_service: null_mut(),
        };
        let mut status = IoStatusBlock {
            status: 0,
            information: 0,
        };
        let mut raw = null_mut();
        // SAFETY: live root handle, bounded single component, valid structures; synchronous
        // open finishes before any buffers or security descriptor are released.
        let result = unsafe {
            NtCreateFile(
                &mut raw,
                access | READ_ATTRIBUTES | SYNCHRONIZE | creation_security_access,
                &mut object,
                &mut status,
                null(),
                0x80,
                if directory {
                    self.config.directory_share
                } else {
                    share_file
                },
                native_disposition,
                options | OPEN_REPARSE_POINT | SYNCHRONOUS_IO_NONALERT,
                null(),
                0,
            )
        };
        if result < 0 {
            // SAFETY: translates NTSTATUS, not thread-local GetLastError.
            let error =
                io::Error::from_raw_os_error(unsafe { RtlNtStatusToDosError(result) } as i32);
            if create_only && error.kind() == io::ErrorKind::AlreadyExists {
                return self.open_at_with_retention(
                    entry_name,
                    access,
                    FILE_OPEN,
                    options,
                    share_file,
                    check,
                    retain_name,
                );
            }
            return Err(if error.kind() == io::ErrorKind::AlreadyExists {
                FsError::AlreadyExists(shown.to_path_buf())
            } else {
                FsError::io(shown, error)
            });
        }
        if raw.is_null() || raw as isize == -1 {
            return Err(FsError::Unavailable(
                "NtCreateFile returned no child handle",
            ));
        }
        const FILE_CREATED: usize = 2;
        // SAFETY: successful NtCreateFile transfers ownership of this handle.
        let file = unsafe { File::from_raw_handle(raw) };
        #[cfg(feature = "testing")]
        if retain_name {
            super::testing::after_empty_create(&file)?;
        }
        let checked = match check {
            Check::NoReparse => attributes(&file, shown),
            Check::ReparseLink => link_attributes(&file, shown),
        };
        if let Err(error) = checked {
            if !retain_name && security.is_some() && status.information == FILE_CREATED {
                let _ = discard_unverified_owner_only(&file, shown);
            }
            return Err(error);
        }
        // A descriptor is only supplied for FILE_CREATE, so this handle is new. Failed
        // temporary entries are disposed; a visible final lock name is never removed here.
        if security.is_some() {
            if status.information != FILE_CREATED {
                if !retain_name {
                    let _ = discard_unverified_owner_only(&file, shown);
                }
                return Err(FsError::Unavailable(
                    "NtCreateFile did not report a new private entry",
                ));
            }
            // Direct permanent creation verifies this same handle in finish_read_open, once,
            // with the same strict predicate as an opted-in later reader.
            if !retain_name {
                if let Err(error) = verify_owner_only_handle(&file, shown) {
                    let _ = discard_unverified_owner_only(&file, shown);
                    return Err(error);
                }
            }
        }
        Ok(file)
    }

    /// `_shared` is the unix "do not require a private directory" policy; Windows checks no ACL or
    /// mode on an existing directory, so it has no effect here.
    pub fn pin(path: &Path, create: bool, options: &StateOptions, _shared: bool) -> Result<Self> {
        let config = Config::from_options(options);
        if path.as_os_str().is_empty() {
            return Err(FsError::BadName(String::new()));
        }
        let absolute = if path.is_absolute() {
            path.to_path_buf()
        } else {
            std::env::current_dir()
                .map_err(|e| FsError::io(path, e))?
                .join(path)
        };
        let mut parts = absolute.components();
        let mut root = PathBuf::new();
        match parts.next() {
            Some(Component::Prefix(p))
                if matches!(
                    p.kind(),
                    Prefix::Disk(_)
                        | Prefix::VerbatimDisk(_)
                        | Prefix::UNC(_, _)
                        | Prefix::VerbatimUNC(_, _)
                ) =>
            {
                root.push(p.as_os_str())
            }
            _ => return Err(FsError::BadName(path.display().to_string())),
        }
        if !matches!(parts.next(), Some(Component::RootDir)) {
            return Err(FsError::BadName(path.display().to_string()));
        }
        root.push("\\");
        let mut current = Self::open_path(&root, config, config.directory_share)?;
        for part in parts {
            match part {
                Component::CurDir => continue,
                Component::Normal(name) => {
                    root.push(name);
                    // A directory this walk creates is opened write-through, like `child`: the
                    // creation is committed before the walk descends into it. Windows has no
                    // directory flush to add (see `Dir::sync`), so this is the strongest
                    // equivalent of publishing each new ancestor.
                    let file = current.open_at(
                        name,
                        1,
                        if create { FILE_OPEN_IF } else { FILE_OPEN },
                        if create {
                            DIRECTORY_FILE | FILE_WRITE_THROUGH
                        } else {
                            DIRECTORY_FILE
                        },
                    )?;
                    current = Self::verified(file, &root, config)?;
                }
                _ => return Err(FsError::BadName(path.display().to_string())),
            }
        }
        // Retain one CreateFileW handle for the state directory, checked against the
        // no-reparse component walk. Any ancestor swap during this final open fails closed.
        // The walk's creation handle may carry DELETE access (private-descriptor cleanup rights),
        // which would make this open a sharing violation without FILE_SHARE_DELETE. Record its
        // identity and release it first; the identity comparison below still fails closed on
        // any swap in between.
        let walked = current.identity(path)?;
        drop(current);
        let pinned = Self::open_path(&absolute, config, config.directory_share)?;
        if walked != pinned.identity(path)? {
            return Err(FsError::IdentityChanged(path.to_path_buf()));
        }
        Ok(pinned)
    }

    pub fn child(&self, name: &str, _policy: SyncPolicy, _shared: bool) -> Result<Self> {
        // Created write-through: the directory entry is committed with the creation.
        let file = self.open_at(
            OsStr::new(name),
            1,
            FILE_OPEN_IF,
            DIRECTORY_FILE | FILE_WRITE_THROUGH,
        )?;
        Self::verified(file, Path::new(name), self.config)
    }

    pub fn stat(&self, name: &str) -> Result<Option<EntryStat>> {
        let file = match self.open_at(OsStr::new(name), READ_ATTRIBUTES, FILE_OPEN, 0) {
            Ok(file) => file,
            Err(e) if e.is_not_found() => return Ok(None),
            Err(e) => return Err(e),
        };
        let m = file.metadata().map_err(|e| FsError::io(name, e))?;
        // The volume serial number and file index of the opened entry, so two names for one file
        // (or one file seen twice) compare equal as they do on unix.
        let key = crate::file_key::FileKey::of_file(&file, Path::new(name))?;
        Ok(Some(EntryStat {
            kind: if m.is_dir() {
                EntryKind::Dir
            } else if m.is_file() {
                EntryKind::File
            } else {
                EntryKind::Other
            },
            size: m.len(),
            dev: key.volume,
            ino: key.index,
            mode: 0,
            modified_unix_ms: m
                .modified()
                .ok()
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_millis() as u64)
                .unwrap_or(0),
        }))
    }

    /// Open a regular child for reading. `share_read_only` opens with `FILE_SHARE_READ` alone, so no
    /// other handle may write, delete or rename the file while this one is open (and the open fails
    /// with a sharing violation while somebody holds it for write).
    /// `require_owner_only` adds READ_CONTROL for the subsequent check on this exact handle.
    /// Ordinary pinned reads retain their existing access mask.
    pub fn open_read_with(&self, name: &str, options: &crate::handle::ReadOptions) -> Result<File> {
        self.open_at_with(
            OsStr::new(name),
            1 | if options.require_owner_only {
                READ_CONTROL
            } else {
                0
            },
            FILE_OPEN,
            NON_DIRECTORY_FILE,
            if options.share_read_only {
                FILE_SHARE_READ
            } else {
                SHARE_READ_WRITE
            },
            Check::NoReparse,
        )
    }

    pub fn create_new(&self, name: &str, retain_name: bool) -> Result<File> {
        self.open_at_with_retention(
            OsStr::new(name),
            0x0012_0116, // FILE_GENERIC_WRITE
            FILE_CREATE,
            NON_DIRECTORY_FILE,
            SHARE_READ_WRITE,
            Check::NoReparse,
            retain_name,
        )
    }

    fn rename(&self, from: &str, to: &str, replace: bool) -> Result<()> {
        let wide = component(OsStr::new(to))?;
        // Refuse an observed reparse destination. If it races this check, the kernel rename
        // replaces the directory entry itself; it never opens or writes through the link.
        if replace {
            if let Some(st) = self.stat(to)? {
                if st.kind != EntryKind::File {
                    return Err(FsError::NotAFile(to.into()));
                }
            }
        }
        // Write-through on the renamed handle, as MOVEFILE_WRITE_THROUGH does.
        let source = self.open_at(
            OsStr::new(from),
            DELETE,
            FILE_OPEN,
            NON_DIRECTORY_FILE | FILE_WRITE_THROUGH,
        )?;
        let offset = offset_of!(RenameInfo, file_name);
        let bytes = size_of::<RenameInfo>() + wide.len() * 2;
        let mut buffer = vec![0usize; bytes.div_ceil(size_of::<usize>())];
        let info = buffer.as_mut_ptr().cast::<RenameInfo>();
        // SAFETY: aligned allocation covers the header and complete UTF-16 name.
        unsafe {
            (*info).replace_if_exists = u8::from(replace);
            (*info).root_directory = self.file.as_raw_handle();
            (*info).file_name_length = (wide.len() * 2) as u32;
            std::ptr::copy_nonoverlapping(
                wide.as_ptr(),
                buffer.as_mut_ptr().cast::<u8>().add(offset).cast::<u16>(),
                wide.len(),
            );
            let mut status = IoStatusBlock {
                status: 0,
                information: 0,
            };
            // The native rename API resolves this single component against RootDirectory.
            // Keep the pinned handle rather than asking Win32 to translate a DOS path.
            let result = NtSetInformationFile(
                source.as_raw_handle(),
                &mut status,
                info.cast(),
                bytes as u32,
                FILE_RENAME_INFORMATION,
            );
            if result < 0 {
                let e = io::Error::from_raw_os_error(RtlNtStatusToDosError(result) as i32);
                return Err(if e.kind() == io::ErrorKind::AlreadyExists {
                    FsError::AlreadyExists(to.into())
                } else {
                    FsError::io(to, e)
                });
            }
        }
        Ok(())
    }

    pub fn rename_replace(&self, from: &str, to: &str) -> Result<()> {
        self.rename(from, to, true)
    }

    pub fn link_new(&self, from: &str, to: &str) -> Result<()> {
        // Windows publishes by atomic no-replace rename rather than a hard link. The
        // caller's subsequent temp unlink sees NotFound, which it already ignores.
        self.rename(from, to, false)
    }

    pub fn unlink(&self, name: &str) -> Result<()> {
        let file = self.open_at(
            OsStr::new(name),
            DELETE,
            FILE_OPEN,
            NON_DIRECTORY_FILE | FILE_WRITE_THROUGH,
        )?;
        mark_delete(&file, name)
    }

    /// Remove an empty directory child through a handle opened without reparse traversal, so a
    /// junction or symlink at `name` is refused ([`FsError::Symlink`]) and never followed. A directory
    /// that still holds entries fails with the OS error (`ERROR_DIR_NOT_EMPTY`).
    pub fn remove_dir(&self, name: &str) -> Result<()> {
        let dir = self.open_at(
            OsStr::new(name),
            DELETE,
            FILE_OPEN,
            DIRECTORY_FILE | FILE_WRITE_THROUGH,
        )?;
        mark_delete(&dir, name)
    }

    /// Remove a symlink or junction child itself: the entry is opened as the reparse point
    /// (`FILE_OPEN_REPARSE_POINT`) and deleted through that handle, so its target is never opened,
    /// touched or removed. Anything that is not a symlink or junction is refused as `InvalidInput`.
    pub fn remove_link(&self, name: &str) -> Result<()> {
        let link = self.open_at_with(
            OsStr::new(name),
            DELETE,
            FILE_OPEN,
            FILE_WRITE_THROUGH,
            SHARE_READ_WRITE_DELETE,
            Check::ReparseLink,
        )?;
        mark_delete(&link, name)
    }

    /// There is no directory flush on Windows, so this does nothing and says so (`None`): the
    /// pinned handle is opened for listing, and `FlushFileBuffers` on it fails with
    /// `ERROR_ACCESS_DENIED` (it needs `GENERIC_WRITE`; Pulse saw the same on NTFS). A directory
    /// handle opened for write would only be flushing NTFS metadata the filesystem journals
    /// anyway. Directory-entry durability comes from the operations themselves: the file is
    /// flushed before publication, and directory creation, the publishing rename and the
    /// removing delete are performed on handles opened `FILE_WRITE_THROUGH` (the mechanism
    /// `MOVEFILE_WRITE_THROUGH` uses), so they commit with the call. A power-loss test has not
    /// been run against that claim.
    pub fn sync(&self, _policy: SyncPolicy) -> io::Result<Option<SyncLevel>> {
        Ok(None)
    }

    pub fn entries(&self, limit: usize) -> Result<Vec<DirEntry>> {
        let _guard = self
            .enumeration
            .lock()
            .map_err(|_| FsError::Unavailable("directory enumeration lock poisoned"))?;
        // FILE_ID_BOTH_DIR_INFO requires 8-byte alignment, including on 32-bit Windows.
        let mut buffer = vec![0u64; 8192];
        let capacity = buffer.len() * size_of::<u64>();
        let mut class = FILE_ID_BOTH_DIRECTORY_RESTART_INFO;
        let mut out = Vec::new();
        loop {
            buffer.fill(0);
            // SAFETY: open directory and writable, aligned 64 KiB buffer.
            if unsafe {
                GetFileInformationByHandleEx(
                    self.file.as_raw_handle(),
                    class,
                    buffer.as_mut_ptr().cast(),
                    capacity as u32,
                )
            } == 0
            {
                let e = io::Error::last_os_error();
                return if e.raw_os_error() == Some(18) {
                    // ERROR_NO_MORE_FILES
                    Ok(out)
                } else {
                    Err(FsError::io(".", e))
                };
            }
            class = FILE_ID_BOTH_DIRECTORY_INFO;
            let mut offset = 0usize;
            loop {
                if offset > capacity - size_of::<DirectoryInfo>() {
                    return Err(FsError::Unavailable(
                        "malformed directory information header",
                    ));
                }
                // SAFETY: bounded header in initialized allocation.
                let info = unsafe {
                    std::ptr::read_unaligned(
                        buffer
                            .as_ptr()
                            .cast::<u8>()
                            .add(offset)
                            .cast::<DirectoryInfo>(),
                    )
                };
                let start = offset + offset_of!(DirectoryInfo, file_name);
                let len = info.file_name_length as usize;
                if len == 0 || !len.is_multiple_of(2) || len > capacity - start {
                    return Err(FsError::Unavailable("malformed directory information name"));
                }
                // SAFETY: bounded even-sized UTF-16 slice, aligned by directory record ABI.
                let name = unsafe {
                    std::slice::from_raw_parts(
                        buffer.as_ptr().cast::<u8>().add(start).cast::<u16>(),
                        len / 2,
                    )
                };
                // A name with unpaired surrogates comes back lossily (it cannot be addressed) rather
                // than failing the whole listing.
                let name = String::from_utf16_lossy(name);
                if name != "." && name != ".." {
                    if out.len() >= limit {
                        return Err(FsError::TooManyEntries(limit));
                    }
                    out.push(DirEntry {
                        name,
                        kind: super::kind_from_attributes(info.attributes),
                    });
                }
                let next = info.next_entry_offset as usize;
                if next == 0 {
                    break;
                }
                if !next.is_multiple_of(8)
                    || next < offset_of!(DirectoryInfo, file_name) + len
                    || next > capacity - offset
                {
                    return Err(FsError::Unavailable(
                        "malformed directory information offset",
                    ));
                }
                offset += next;
            }
        }
    }

    /// Reclaim only generated temps whose enumerated full file identity still matches the
    /// opened no-reparse handle. Public listings keep using `FILE_ID_BOTH_DIR_INFO`; cleanup uses
    /// its private extended-ID path so it never truncates an identity to 64 bits.
    pub(super) fn sweep_temps(&self) -> Result<usize> {
        let _guard = self
            .enumeration
            .lock()
            .map_err(|_| FsError::Unavailable("directory enumeration lock poisoned"))?;
        crate::windows_temp_sweep::sweep(&self.file)
    }
}

#[cfg(all(test, windows))]
#[path = "windows_tests.rs"]
mod tests;

//! Owner-only files and directories.
//!
//! Donor: CodeRight `private_fs` (perm/atomic/sweep). Unix uses mode bits applied at
//! creation time (never chmod-after-create for new files); Windows applies one protected
//! owner-only DACL through native security APIs. There is no weaker fallback: a failed native
//! step is an error, never a partial hardening reported as success.

use crate::atomic::{atomic_write_with, AtomicOptions};
use crate::error::{FsError, Result};
use std::path::{Path, PathBuf};

pub const FILE_MODE_OWNER_ONLY: u32 = 0o600;
pub const DIR_MODE_OWNER_ONLY: u32 = 0o700;
/// Mode of an owner-only executable file on Unix (owner read, write and execute).
pub const EXECUTABLE_MODE_OWNER_ONLY: u32 = 0o700;

/// Narrow an existing file or directory to owner-only. A missing path is a no-op.
/// Symlinks are never followed on unix: a symlink is refused rather than chmod-ing its target.
/// On macOS an entry that carries an extended ACL is **refused** ([`FsError::UnsafeAcl`]) after its
/// mode has been narrowed: the ACL is left as it is, because removing it cannot revoke access
/// through a descriptor somebody already holds open, so a repair would report an owner-only
/// entry that was not.
pub fn restrict_owner_only(path: &Path) -> Result<()> {
    restrict_owner_only_impl(path)
}

#[cfg(unix)]
fn restrict_owner_only_impl(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let meta = match std::fs::symlink_metadata(path) {
        Ok(meta) => meta,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(FsError::io(path, e)),
    };
    if meta.file_type().is_symlink() {
        return Err(FsError::Symlink(path.to_path_buf()));
    }
    let mode = if meta.is_dir() {
        DIR_MODE_OWNER_ONLY
    } else {
        FILE_MODE_OWNER_ONLY
    };
    if meta.permissions().mode() & 0o7777 != mode {
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode))
            .map_err(|e| FsError::io(path, e))?;
    }
    // The mode bits are only half of the guarantee: on macOS an ACL `allow` entry is evaluated
    // before them, so a `0600` file can still be readable by others. An ACL is not removed (that
    // cannot revoke an open descriptor); the entry is refused, so the caller knows it is not
    // owner-only.
    //
    // The ACL is read by path. The entry is NOT opened: callers apply this to live files
    // (rightkit-db hardens `<db>-wal` and `<db>-shm` on every open), and closing a descriptor
    // releases every POSIX record lock this process holds on the file, SQLite's included.
    if cfg!(target_os = "macos")
        && (meta.is_file() || meta.is_dir())
        && crate::acl::existing_has_allow_acl(path)?
    {
        return Err(FsError::UnsafeAcl(path.to_path_buf()));
    }
    Ok(())
}

#[cfg(not(any(unix, windows)))]
fn restrict_owner_only_impl(_path: &Path) -> Result<()> {
    Ok(())
}

/// True when no group/other access exists on unix: no group or other mode bits and, on macOS, no
/// extended ACL (an `allow` entry is evaluated before the mode bits). On macOS an entry that
/// cannot be opened to read its ACL is reported as not owner-only, because that cannot be
/// proven.
///
/// On Windows this is a **verify-only trust check**: it reads the entry's owner and DACL through a
/// no-reparse handle and is true when the owner is this process's `TokenUser` (or an enabled
/// owner-capable group of its token, in practice Administrators in an elevated token) **and** the DACL
/// grants access only to principals that cannot be a foreign party:
///
/// - the current user,
/// - `NT AUTHORITY\SYSTEM` (`S-1-5-18`),
/// - `BUILTIN\Administrators` (`S-1-5-32-544`),
/// - `CREATOR OWNER` (`S-1-3-0`) when the entry is inherit-only (it grants nothing on this object and
///   is replaced by the creator in what inherits it).
///
/// The ACEs may be explicit or **inherited**, and the DACL need not be protected, so a file or
/// directory made below `%LOCALAPPDATA%` (whose ACL is `SYSTEM`, `Administrators` and the user,
/// inherited) is owner-only without the crate having rewritten its ACL (rightkit#676, rightkit#517).
/// Any `allow` ACE for another user, `Everyone`, `Users`, `Authenticated Users` or any other
/// principal makes the answer `false`, as do a missing (NULL) DACL, an unreadable ACE and any ACE type
/// this check does not understand (it fails closed). `deny` ACEs cannot widen access and are ignored.
/// Unsupported ACL filesystems and unreadable security metadata are errors.
///
/// This is a read of the state now, not a guarantee for later: whoever may change the DACL can change
/// the answer. The exact form this crate itself writes (one protected ACE for the user) is checked by
/// [`is_owner_only_strict`]; the objects this crate creates are verified against that stricter form
/// before any byte is written.
pub fn is_owner_only(path: &Path) -> Result<bool> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let meta = std::fs::symlink_metadata(path).map_err(|e| FsError::io(path, e))?;
        if meta.permissions().mode() & 0o077 != 0 {
            return Ok(false);
        }
        if cfg!(target_os = "macos") && (meta.is_file() || meta.is_dir()) {
            // By path, never by opening: see `restrict_owner_only`.
            return Ok(!crate::acl::existing_has_allow_acl(path)?);
        }
        Ok(true)
    }
    #[cfg(windows)]
    {
        let file = open_owner_only_handle(path, false)?;
        Ok(private_trust_handle(&file, path, true)? == Trust::Private)
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = path;
        Ok(true)
    }
}

/// The exact owner-only form this crate writes. Unix: the same as [`is_owner_only`]. Windows: true
/// only for an object owned by this process's `TokenUser` (or an enabled owner-capable token group)
/// whose DACL is **protected** and holds exactly one ACE, a full-control `allow` for the current user
/// (inheritable on a directory). Unlike [`is_owner_only`] it rejects an inherited ACL and an extra
/// `SYSTEM` or `Administrators` ACE, so it is `false` for a file this crate did not harden.
pub fn is_owner_only_strict(path: &Path) -> Result<bool> {
    #[cfg(windows)]
    {
        let file = open_owner_only_handle(path, false)?;
        is_owner_only_handle(&file, path)
    }
    #[cfg(not(windows))]
    {
        is_owner_only(path)
    }
}

/// [`is_owner_only`] as a checked call: `Ok(())` when `path` is owner-only and owned by the current
/// user, else the reason. For a caller that must refuse rather than branch (a trust check on a file
/// or directory it did not make, such as a runtime store below `%LOCALAPPDATA%`).
///
/// - [`FsError::NotOwned`]: owned by somebody else (Unix: `st_uid` is not the effective user;
///   Windows: the owner is neither the token user nor an enabled owner-capable group).
/// - [`FsError::TooPermissive`]: another principal can reach it (Unix mode bits or, on macOS, an
///   ACL `allow` entry; Windows: an `allow` ACE as described on [`is_owner_only`]).
/// - [`FsError::Symlink`]: `path` is a symlink or reparse point (never followed).
///
/// Nothing is changed or repaired; [`restrict_owner_only`] is the repair.
pub fn verify_owner_only(path: &Path) -> Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let meta = std::fs::symlink_metadata(path).map_err(|e| FsError::io(path, e))?;
        if meta.file_type().is_symlink() {
            return Err(FsError::Symlink(path.to_path_buf()));
        }
        // SAFETY: geteuid has no preconditions.
        if meta.uid() != unsafe { libc::geteuid() } {
            return Err(FsError::NotOwned(path.to_path_buf()));
        }
        if is_owner_only(path)? {
            Ok(())
        } else {
            Err(FsError::TooPermissive(path.to_path_buf()))
        }
    }
    #[cfg(windows)]
    {
        let file = open_owner_only_handle(path, false)?;
        match private_trust_handle(&file, path, true)? {
            Trust::Private => Ok(()),
            Trust::ForeignOwner => Err(FsError::NotOwned(path.to_path_buf())),
            Trust::ForeignAccess => Err(FsError::TooPermissive(path.to_path_buf())),
        }
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = path;
        Ok(())
    }
}

/// What a DACL inspection concluded (Windows).
#[cfg(any(windows, test))]
#[cfg_attr(not(windows), allow(dead_code))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Trust {
    Private,
    ForeignOwner,
    ForeignAccess,
}

/// What an ACE does, from its type byte: `Allow` (`ACCESS_ALLOWED` and the callback form, whose
/// trustee SID sits right after the access mask), `Deny` (the four deny types, which cannot widen
/// access) or `Other` (object, compound and every unknown type: not understood, so not trusted).
#[cfg(any(windows, test))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AceKind {
    Allow,
    Deny,
    Other,
}

#[cfg(any(windows, test))]
fn ace_kind(ace_type: u8) -> AceKind {
    match ace_type {
        0 | 9 => AceKind::Allow,
        1 | 6 | 10 | 12 => AceKind::Deny,
        _ => AceKind::Other,
    }
}

/// `INHERIT_ONLY_ACE`: the ACE grants nothing on this object, only on what inherits it.
#[cfg(any(windows, test))]
const INHERIT_ONLY_ACE: u8 = 0x08;

/// Whether an `allow` ACE for this trustee leaves the object owner-only: the current user, SYSTEM
/// (`S-1-5-18`), BUILTIN\Administrators (`S-1-5-32-544`), or CREATOR OWNER (`S-1-3-0`) on an
/// inherit-only ACE. `authority` is the 48-bit identifier authority.
#[cfg(any(windows, test))]
fn trustee_is_acceptable(
    is_current_user: bool,
    authority: u64,
    sub_authorities: &[u32],
    ace_flags: u8,
) -> bool {
    if is_current_user {
        return true;
    }
    match (authority, sub_authorities) {
        (5, [18]) | (5, [32, 544]) => true,
        (3, [0]) => ace_flags & INHERIT_ONLY_ACE != 0,
        _ => false,
    }
}

/// Whether one ACE leaves the object owner-only: a `deny` ACE always does (it cannot widen access);
/// an `allow` ACE does when its trustee is acceptable ([`trustee_is_acceptable`]); an ACE of any
/// other type, or an `allow` ACE whose trustee could not be read (`None`), does not (fail closed).
/// `trustee` is `(is_current_user, authority, sub_authorities)`.
#[cfg(any(windows, test))]
fn ace_is_acceptable(ace_type: u8, ace_flags: u8, trustee: Option<(bool, u64, &[u32])>) -> bool {
    match ace_kind(ace_type) {
        AceKind::Deny => true,
        AceKind::Other => false,
        AceKind::Allow => match trustee {
            Some((is_user, authority, subs)) => {
                trustee_is_acceptable(is_user, authority, subs, ace_flags)
            }
            None => false,
        },
    }
}

/// Create `dir` and any missing ancestors. Each *newly created* directory is owner-only
/// before a child is created inside it; pre-existing ancestors are left alone, and the leaf
/// is always hardened. A symlinked leaf is refused. This does not sync directories: it is not a
/// durable operation (the durable form is [`crate::atomic::create_dir_all_durable`]). On macOS a
/// directory is not created under a parent whose ACL would give it an inheritable `allow` entry, and
/// one that got an `allow` entry anyway is removed again ([`FsError::UnsafeAcl`]).
pub fn ensure_private_dir(dir: &Path) -> Result<()> {
    if dir.as_os_str().is_empty() {
        return Err(FsError::io(
            dir,
            std::io::Error::new(std::io::ErrorKind::InvalidInput, "empty path"),
        ));
    }
    let mut missing: Vec<PathBuf> = Vec::new();
    for ancestor in dir.ancestors() {
        if ancestor.as_os_str().is_empty() {
            break;
        }
        match ancestor.symlink_metadata() {
            Ok(_) => break,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                missing.push(ancestor.to_path_buf());
            }
            Err(error) => return Err(FsError::io(ancestor, error)),
        }
    }
    for path in missing.iter().rev() {
        create_private_dir_one(path)?;
    }
    let meta = std::fs::symlink_metadata(dir).map_err(|e| FsError::io(dir, e))?;
    if meta.file_type().is_symlink() {
        return Err(FsError::Symlink(dir.to_path_buf()));
    }
    if !meta.is_dir() {
        return Err(FsError::NotADirectory(dir.to_path_buf()));
    }
    restrict_owner_only(dir)
}

fn create_private_dir_one(path: &Path) -> Result<()> {
    #[cfg(unix)]
    let result = {
        use std::os::unix::fs::DirBuilderExt;
        // macOS: refuse a parent whose ACL would give the new directory an inheritable `allow` entry.
        if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
            crate::acl::guard_parent_path(parent, path)?;
        }
        let made = std::fs::DirBuilder::new()
            .mode(DIR_MODE_OWNER_ONLY)
            .create(path);
        if made.is_ok() {
            // A directory that carries an `allow` entry anyway is empty: remove it and refuse.
            if let Err(error) = crate::acl::refuse_acl_path(path) {
                let _ = std::fs::remove_dir(path);
                return Err(error);
            }
        }
        made
    };
    #[cfg(windows)]
    let result = create_dir_owner_only(path);
    #[cfg(not(any(unix, windows)))]
    let result = std::fs::create_dir(path);
    let created = match result {
        Ok(()) => true,
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => false,
        Err(e) => return Err(FsError::io(path, e)),
    };
    #[cfg(not(windows))]
    let _ = created;
    #[cfg(windows)]
    if !created {
        restrict_owner_only(path)?;
    }
    #[cfg(not(any(unix, windows)))]
    restrict_owner_only(path)?;
    Ok(())
}

/// Atomically write an owner-only file (the temp inode is owner-only from creation, so the
/// secret is never visible under the destination name with a permissive mode).
pub fn write_private_file(path: &Path, bytes: &[u8]) -> Result<()> {
    use std::io::Write;
    atomic_write_with(path, AtomicOptions::private(), |f| f.write_all(bytes))
}

pub fn write_private_text(path: &Path, text: &str) -> Result<()> {
    write_private_file(path, text.as_bytes())
}

/// Atomically write an owner-only executable file (M8-O10: helper and askpass scripts).
///
/// Unix: the published file is mode `0700` ([`EXECUTABLE_MODE_OWNER_ONLY`]). The temp inode is
/// created `0600` and set to `0700` through its descriptor before it is published, so the file
/// never exists under the destination name with a broader mode, and never without its execute
/// bit. Windows: there is no execute bit; the file gets the same owner-only DACL as
/// [`write_private_file`] and is executable by file type, so the caller picks the extension.
/// Like every atomic write here the destination is replaced as a whole, and a name shaped like
/// a generated temp name is refused ([`FsError::BadName`]).
pub fn write_private_executable(path: &Path, bytes: &[u8]) -> Result<()> {
    let mut writer = crate::atomic::AtomicWriter::create(path, AtomicOptions::private())?;
    writer.write_all(bytes)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let permissions = std::fs::Permissions::from_mode(EXECUTABLE_MODE_OWNER_ONLY);
        if let Err(e) = writer.file_mut().set_permissions(permissions) {
            let temp = writer.temp_path().to_path_buf();
            return Err(FsError::io(temp, e));
        }
    }
    writer.commit()
}

/// Exclusively create an owner-only file, never following a symlink at `path`.
/// For files that are appended to or locked rather than replaced (logs, lock files).
///
/// The file is owner-only from the instant it exists: Unix creates it `0600`, Windows creates it
/// with an owner-only security descriptor passed to `CreateFileW`, so no principal the parent's
/// inherited ACL admits can open it before it is restricted and keep a readable handle. A name
/// shaped like a temp name this crate generates is refused ([`FsError::BadName`]); a sweep would
/// delete such a file.
pub fn create_private_new(path: &Path) -> Result<std::fs::File> {
    if let Some(name) = path.file_name() {
        crate::atomic::reject_reserved_name(&name.to_string_lossy())?;
    }
    create_private_new_impl(path)
}

#[cfg(windows)]
fn create_private_new_impl(path: &Path) -> Result<std::fs::File> {
    create_new_owner_only(path).map_err(|e| FsError::io(path, e))
}

#[cfg(not(windows))]
fn create_private_new_impl(path: &Path) -> Result<std::fs::File> {
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options
            .mode(FILE_MODE_OWNER_ONLY)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
    }
    // macOS: refuse a parent whose ACL would give the new file an inheritable `allow` entry, before
    // creating.
    #[cfg(unix)]
    crate::acl::guard_parent_path(
        path.parent()
            .filter(|p| !p.as_os_str().is_empty())
            .unwrap_or(Path::new(".")),
        path,
    )?;
    let file = options.open(path).map_err(|e| FsError::io(path, e))?;
    #[cfg(unix)]
    // A file that carries an `allow` entry anyway is still empty: remove it and refuse.
    if let Err(error) = crate::acl::refuse_acl(&file, path) {
        drop(file);
        let _ = std::fs::remove_file(path);
        return Err(error);
    }
    #[cfg(not(unix))]
    restrict_owner_only(path)?;
    Ok(file)
}

/// Owner-only repair for the named entries directly inside `dir`, plus `dir` itself.
/// One level deep and by exact name only: foreign entries are untouched and no symlink is
/// followed. Returns how many entries were narrowed.
pub fn sweep_owner_only(dir: &Path, owned_names: &[&str]) -> Result<usize> {
    restrict_owner_only(dir)?;
    let mut narrowed = 0;
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(FsError::io(dir, e)),
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        if owned_names.iter().any(|owned| name == *owned)
            && (cfg!(windows) || !is_owner_only(&entry.path())?)
        {
            restrict_owner_only(&entry.path())?;
            narrowed += 1;
        }
    }
    Ok(narrowed)
}

#[cfg(windows)]
fn restrict_owner_only_impl(path: &Path) -> crate::error::Result<()> {
    let file = match open_owner_only_handle(path, true) {
        Ok(file) => file,
        Err(error) if error.is_not_found() => return Ok(()),
        Err(error) => return Err(error),
    };
    // Fail closed. The native call replaces the whole DACL (one protected ACE for the current
    // user, nothing inherited). An `icacls /inheritance:r /grant:r` fallback is not equivalent: it
    // only replaces the grants for the one SID, so an explicit ACE for another principal (an
    // Everyone read ACE on the destination, say) would survive and the result would be reported
    // as owner-only.
    native_restrict_owner_only(&file, path)
}

#[cfg(windows)]
fn current_process_token_user(path: &Path) -> crate::error::Result<Vec<usize>> {
    current_process_token_info(path, 1) // TokenUser
}

/// Raw `GetTokenInformation` buffer for the current process token (pointer-aligned storage).
#[cfg(windows)]
fn current_process_token_info(path: &Path, class: u32) -> crate::error::Result<Vec<usize>> {
    use std::ffi::c_void;

    type Handle = *mut c_void;
    const TOKEN_QUERY: u32 = 0x0008;
    let class_id = class;

    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn OpenProcessToken(process: Handle, access: u32, token: *mut Handle) -> i32;
        fn GetTokenInformation(
            token: Handle,
            class: u32,
            buffer: *mut c_void,
            len: u32,
            needed: *mut u32,
        ) -> i32;
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn GetCurrentProcess() -> Handle;
        fn CloseHandle(handle: Handle) -> i32;
    }

    unsafe {
        let mut token = std::ptr::null_mut();
        if OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token) == 0 {
            return Err(crate::error::FsError::io(
                path,
                std::io::Error::last_os_error(),
            ));
        }
        let mut needed = 0;
        let _ = GetTokenInformation(token, class_id, std::ptr::null_mut(), 0, &mut needed);
        if needed == 0 {
            let error = std::io::Error::last_os_error();
            let _ = CloseHandle(token);
            return Err(crate::error::FsError::io(path, error));
        }
        let words = (needed as usize).div_ceil(std::mem::size_of::<usize>());
        let mut token_info = vec![0usize; words];
        if GetTokenInformation(
            token,
            class_id,
            token_info.as_mut_ptr().cast(),
            needed,
            &mut needed,
        ) == 0
        {
            let error = std::io::Error::last_os_error();
            let _ = CloseHandle(token);
            return Err(crate::error::FsError::io(path, error));
        }
        let _ = CloseHandle(token);
        Ok(token_info)
    }
}

/// `SE_GROUP_ENABLED`: the group is active for access checks in this token. An elevated
/// administrator holds BUILTIN\\Administrators enabled; a filtered (non-elevated) token holds it
/// deny-only, which is not enabled.
#[cfg(any(windows, test))]
const SE_GROUP_ENABLED: u32 = 0x0000_0004;
#[cfg(any(windows, test))]
const SE_GROUP_USE_FOR_DENY_ONLY: u32 = 0x0000_0010;

/// `SE_GROUP_OWNER`: the group may be assigned as the owner of objects the token creates.
#[cfg(any(windows, test))]
const SE_GROUP_OWNER: u32 = 0x0000_0008;

/// True for the well-known broad SIDs that must never be accepted as an owner: Everyone
/// (S-1-1-0), LOCAL (S-1-2-0), INTERACTIVE (S-1-5-4), Authenticated Users (S-1-5-11) and
/// BUILTIN\Users (S-1-5-32-545). `authority` is the 48-bit identifier authority.
#[cfg(any(windows, test))]
fn sid_is_broad(authority: u64, sub_authorities: &[u32]) -> bool {
    matches!(
        (authority, sub_authorities),
        (1, [0]) | (2, [0]) | (5, [4]) | (5, [11]) | (5, [32, 545])
    )
}

/// Decides whether an existing object's owner may be repaired to owner-only. Accepts only the
/// token user, or a group that is flagged `SE_GROUP_OWNER` and `SE_GROUP_ENABLED` and is not
/// deny-only (in practice BUILTIN\Administrators in an elevated token, which is where objects
/// created by an elevated process are owned). An owner implicitly holds WRITE_DAC, so a broad
/// owner would leave the object writable by others after repair; an ordinary enabled group
/// (Everyone, Users, Authenticated Users, INTERACTIVE, LOCAL, ...) is therefore never accepted,
/// and `is_broad` hard-denies those well-known SIDs even if a token flags them as owner groups.
#[cfg(any(windows, test))]
fn owner_is_trusted<S: PartialEq>(
    owner: &S,
    user: &S,
    groups: &[(S, u32)],
    is_broad: &dyn Fn(&S) -> bool,
) -> bool {
    if owner == user {
        return true;
    }
    if is_broad(owner) {
        return false;
    }
    groups.iter().any(|(sid, attributes)| {
        sid == owner
            && attributes & SE_GROUP_ENABLED != 0
            && attributes & SE_GROUP_OWNER != 0
            && attributes & SE_GROUP_USE_FOR_DENY_ONLY == 0
    })
}

/// True when `owner` is the current user or an enabled owner-capable, non-broad group of the token.
#[cfg(windows)]
fn owner_matches_token(
    owner: *mut std::ffi::c_void,
    user: *mut std::ffi::c_void,
    path: &Path,
) -> crate::error::Result<bool> {
    use std::ffi::c_void;
    #[repr(C)]
    struct SidAndAttributes {
        sid: *mut c_void,
        attributes: u32,
    }
    #[repr(C)]
    struct TokenGroups {
        count: u32,
        groups: [SidAndAttributes; 1],
    }
    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn EqualSid(left: *mut c_void, right: *mut c_void) -> i32;
    }
    const TOKEN_GROUPS_CLASS: u32 = 2;
    if owner.is_null() {
        return Ok(false);
    }
    // SAFETY: both SIDs are live and validated by the callers' queries.
    if unsafe { EqualSid(owner, user) } != 0 {
        return Ok(true);
    }
    let buffer = current_process_token_info(path, TOKEN_GROUPS_CLASS)?;
    let header = buffer.as_ptr().cast::<TokenGroups>();
    // SAFETY: a TOKEN_GROUPS buffer starts with its count followed by that many entries, all
    // inside the retained allocation.
    let (count, first) = unsafe { ((*header).count as usize, (*header).groups.as_ptr()) };
    // Reduce each group to "is it the owner" (1) or not (2) so the shared rule decides.
    let groups: Vec<(u8, u32)> = (0..count)
        .map(|index| {
            // SAFETY: index < GroupCount; group SIDs live in `buffer`, owner is live.
            let entry = unsafe { &*first.add(index) };
            let same = unsafe { EqualSid(owner, entry.sid) } != 0;
            (if same { 1 } else { 2 }, entry.attributes)
        })
        .collect();
    // SAFETY: the owner SID is live and valid (checked non-null above); a SID is revision,
    // sub-authority count (<= 15), 6 big-endian authority bytes, then that many u32 values.
    let owner_broad = unsafe {
        let bytes = owner.cast::<u8>();
        let count = (*bytes.add(1)).min(15) as usize;
        let mut authority = 0u64;
        for i in 0..6 {
            authority = (authority << 8) | u64::from(*bytes.add(2 + i));
        }
        let subs: Vec<u32> = (0..count)
            .map(|i| std::ptr::read_unaligned(bytes.add(8 + 4 * i).cast::<u32>()))
            .collect();
        sid_is_broad(authority, &subs)
    };
    Ok(owner_is_trusted(&1u8, &0u8, &groups, &|_| owner_broad))
}

#[cfg(windows)]
pub(crate) fn current_process_sid_string(path: &Path) -> crate::error::Result<String> {
    use std::ffi::c_void;
    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn ConvertSidToStringSidW(sid: *mut c_void, string_sid: *mut *mut u16) -> i32;
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn LocalFree(memory: *mut c_void) -> *mut c_void;
    }

    let token_info = current_process_token_user(path)?;
    unsafe {
        let sid = *(token_info.as_ptr().cast::<*mut c_void>());
        let mut sid_text = std::ptr::null_mut();
        if ConvertSidToStringSidW(sid, &mut sid_text) == 0 {
            return Err(crate::error::FsError::io(
                path,
                std::io::Error::last_os_error(),
            ));
        }
        let sid_len = (0..).take_while(|&i| *sid_text.add(i) != 0).count();
        let sid_string = String::from_utf16_lossy(std::slice::from_raw_parts(sid_text, sid_len));
        let _ = LocalFree(sid_text.cast());
        Ok(sid_string)
    }
}

/// Read or repair only through this no-reparse handle. Repair asks for
/// `READ_CONTROL | WRITE_DAC | WRITE_OWNER` (so a trusted group owner can be rewritten to the
/// token user) and shares read, write and delete, so hardening a file another handle holds open
/// (SQLite) neither fails with a sharing violation nor releases that handle's locks. (An earlier
/// `MAXIMUM_ALLOWED` open added DELETE and broke that; its claimed inherited-ACE propagation
/// effect was never verified.) When `WRITE_OWNER` itself is refused, the open is retried without
/// it: an object already owned by the token user still repairs its DACL through the owner's
/// implicit `WRITE_DAC`, and one whose owner would have to change then fails closed in
/// `native_restrict_owner_only` instead of being reported repaired.
#[cfg(windows)]
fn open_owner_only_handle(path: &Path, repair: bool) -> crate::error::Result<std::fs::File> {
    use std::ffi::c_void;
    use std::os::windows::ffi::OsStrExt;
    use std::os::windows::io::{AsRawHandle, FromRawHandle};

    #[repr(C)]
    struct AttributeTagInfo {
        attributes: u32,
        tag: u32,
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn CreateFileW(
            name: *const u16,
            access: u32,
            share: u32,
            security: *const c_void,
            disposition: u32,
            flags: u32,
            template: *mut c_void,
        ) -> *mut c_void;
        fn GetFileInformationByHandleEx(
            file: *mut c_void,
            class: i32,
            info: *mut c_void,
            size: u32,
        ) -> i32;
    }

    // Repair rewrites the DACL and, for a trusted group owner, the owner, so it asks for
    // WRITE_OWNER as well; MAXIMUM_ALLOWED would add DELETE and conflict with a holder (SQLite)
    // that did not share delete. Share read, write and delete so this handle never blocks or is
    // blocked.
    const WRITE_DAC: u32 = 0x0004_0000;
    const WRITE_OWNER: u32 = 0x0008_0000;
    const ERROR_ACCESS_DENIED: i32 = 5;
    const FILE_SHARE_READ_WRITE_DELETE: u32 = 0x7;
    const READ_CONTROL: u32 = 0x0002_0000;
    const FILE_READ_ATTRIBUTES: u32 = 0x80;
    const OPEN_EXISTING: u32 = 3;
    const FILE_FLAG_BACKUP_SEMANTICS: u32 = 0x0200_0000;
    const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
    const FILE_ATTRIBUTE_TAG_INFO: i32 = 9;
    const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x400;

    let wide: Vec<u16> = path.as_os_str().encode_wide().chain(Some(0)).collect();
    if wide[..wide.len() - 1].contains(&0) {
        return Err(FsError::BadName(path.display().to_string()));
    }
    let read_access = READ_CONTROL | FILE_READ_ATTRIBUTES;
    let accesses: &[u32] = if repair {
        &[
            read_access | WRITE_DAC | WRITE_OWNER,
            read_access | WRITE_DAC,
        ]
    } else {
        &[read_access]
    };
    let mut raw = std::ptr::null_mut();
    for (index, access) in accesses.iter().enumerate() {
        // SAFETY: `wide` is NUL-terminated and no security attribute is retained by this open.
        raw = unsafe {
            CreateFileW(
                wide.as_ptr(),
                *access,
                FILE_SHARE_READ_WRITE_DELETE,
                std::ptr::null(),
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                std::ptr::null_mut(),
            )
        };
        if raw as isize != -1 && !raw.is_null() {
            break;
        }
        let error = std::io::Error::last_os_error();
        // Only a refused WRITE_OWNER retries with the smaller request (see the doc comment).
        if !(index + 1 < accesses.len() && error.raw_os_error() == Some(ERROR_ACCESS_DENIED)) {
            return Err(FsError::io(path, error));
        }
        raw = std::ptr::null_mut();
    }
    if raw as isize == -1 || raw.is_null() {
        return Err(FsError::io(path, std::io::Error::last_os_error()));
    }
    // SAFETY: CreateFileW returned a fresh owned handle.
    let file = unsafe { std::fs::File::from_raw_handle(raw) };
    let mut info = AttributeTagInfo {
        attributes: 0,
        tag: 0,
    };
    // SAFETY: live handle and correctly sized output structure.
    if unsafe {
        GetFileInformationByHandleEx(
            file.as_raw_handle(),
            FILE_ATTRIBUTE_TAG_INFO,
            (&mut info as *mut AttributeTagInfo).cast(),
            std::mem::size_of::<AttributeTagInfo>() as u32,
        )
    } == 0
    {
        return Err(FsError::io(path, std::io::Error::last_os_error()));
    }
    if info.attributes & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
        return Err(FsError::Symlink(path.to_path_buf()));
    }
    Ok(file)
}

#[cfg(windows)]
fn require_persistent_acls(file: &std::fs::File, shown: &Path) -> crate::error::Result<()> {
    use std::os::windows::io::AsRawHandle;
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn GetVolumeInformationByHandleW(
            file: *mut std::ffi::c_void,
            volume_name: *mut u16,
            volume_name_size: u32,
            serial: *mut u32,
            max_component: *mut u32,
            flags: *mut u32,
            filesystem_name: *mut u16,
            filesystem_name_size: u32,
        ) -> i32;
    }
    const FILE_PERSISTENT_ACLS: u32 = 0x8;
    let mut flags = 0;
    // SAFETY: only the flags out-parameter is requested for a live file handle.
    if unsafe {
        GetVolumeInformationByHandleW(
            file.as_raw_handle(),
            std::ptr::null_mut(),
            0,
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            &mut flags,
            std::ptr::null_mut(),
            0,
        )
    } == 0
    {
        return Err(FsError::io(shown, std::io::Error::last_os_error()));
    }
    if flags & FILE_PERSISTENT_ACLS == 0 {
        return Err(FsError::Unavailable(
            "Windows filesystem lacks persistent ACLs",
        ));
    }
    Ok(())
}

/// The strict verdict: the exact protected single-ACE form this crate writes. False for a readable
/// but non-private descriptor. Query and metadata errors propagate.
#[cfg(windows)]
pub(crate) fn is_owner_only_handle(
    file: &std::fs::File,
    shown: &Path,
) -> crate::error::Result<bool> {
    private_trust_handle(file, shown, false).map(|trust| trust == Trust::Private)
}

/// Inspect the owner and DACL of an open handle. `tolerant` false is the strict form (protected DACL,
/// exactly one full-control ACE for the current user); `tolerant` true accepts inherited and
/// unprotected DACLs whose every `allow` ACE names the current user, SYSTEM, Administrators (or an
/// inherit-only CREATOR OWNER), see [`is_owner_only`].
#[cfg(windows)]
fn private_trust_handle(
    file: &std::fs::File,
    shown: &Path,
    tolerant: bool,
) -> crate::error::Result<Trust> {
    use std::ffi::c_void;
    use std::os::windows::io::AsRawHandle;
    #[repr(C)]
    struct AceHeader {
        ace_type: u8,
        ace_flags: u8,
        ace_size: u16,
    }
    #[repr(C)]
    struct AclSizeInformation {
        ace_count: u32,
        acl_bytes_in_use: u32,
        acl_bytes_free: u32,
    }
    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn GetSecurityInfo(
            object: *mut c_void,
            object_type: u32,
            information: u32,
            owner: *mut *mut c_void,
            group: *mut *mut c_void,
            dacl: *mut *mut c_void,
            sacl: *mut *mut c_void,
            descriptor: *mut *mut c_void,
        ) -> u32;
        fn EqualSid(left: *mut c_void, right: *mut c_void) -> i32;
        fn GetSecurityDescriptorControl(
            descriptor: *mut c_void,
            control: *mut u16,
            revision: *mut u32,
        ) -> i32;
        fn IsValidAcl(acl: *mut c_void) -> i32;
        fn GetAclInformation(
            acl: *mut c_void,
            information: *mut c_void,
            length: u32,
            class: u32,
        ) -> i32;
        fn GetAce(acl: *mut c_void, index: u32, ace: *mut *mut c_void) -> i32;
        fn IsValidSid(sid: *mut c_void) -> i32;
        fn GetLengthSid(sid: *mut c_void) -> u32;
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn LocalFree(memory: *mut c_void) -> *mut c_void;
    }
    const SE_FILE_OBJECT: u32 = 1;
    const OWNER_SECURITY_INFORMATION: u32 = 0x1;
    const DACL_SECURITY_INFORMATION: u32 = 0x4;
    const SE_DACL_PROTECTED: u16 = 0x1000;
    const ACL_SIZE_INFORMATION: u32 = 2;
    const ACCESS_ALLOWED_ACE_TYPE: u8 = 0;
    const OBJECT_INHERIT_ACE: u8 = 0x1;
    const CONTAINER_INHERIT_ACE: u8 = 0x2;
    const FILE_ALL_ACCESS: u32 = 0x001f_01ff;
    const ACCESS_ALLOWED_ACE_PREFIX: usize = 8;
    const SID_HEADER_SIZE: usize = 8;
    const SID_MAX_SUB_AUTHORITIES: u8 = 15;

    /// The strict form: exactly one ACE, a full-control `allow` for `sid`, with the inherit flags the
    /// object kind needs and nothing else.
    fn strict_single_ace(
        dacl: *mut c_void,
        count: u32,
        directory: bool,
        sid: *mut c_void,
        shown: &Path,
    ) -> crate::error::Result<bool> {
        if count != 1 {
            return Ok(false);
        }
        let mut ace = std::ptr::null_mut();
        // SAFETY: validated ACL has exactly one indexed ACE.
        if unsafe { GetAce(dacl, 0, &mut ace) } == 0 {
            return Err(FsError::io(shown, std::io::Error::last_os_error()));
        }
        if ace.is_null() {
            return Ok(false);
        }
        // SAFETY: GetAce returned an ACE from native-validated ACL storage.
        let header = unsafe { &*(ace.cast::<AceHeader>()) };
        if header.ace_type != ACCESS_ALLOWED_ACE_TYPE {
            return Ok(false);
        }
        let expected_flags = if directory {
            OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE
        } else {
            0
        };
        // ACCESS_ALLOWED_ACE stores its access mask immediately after ACE_HEADER and SID at +8.
        let ace_size = usize::from(header.ace_size);
        if header.ace_flags != expected_flags
            || ace_size < ACCESS_ALLOWED_ACE_PREFIX + SID_HEADER_SIZE
        {
            return Ok(false);
        }
        // SAFETY: AceSize establishes both the mask and SID offsets within this ACE.
        let bytes = ace.cast::<u8>();
        let mask = unsafe { *(bytes.add(4).cast::<u32>()) };
        let ace_sid = unsafe { bytes.add(ACCESS_ALLOWED_ACE_PREFIX).cast::<c_void>() };
        // SAFETY: ACE size contains SID's fixed revision/count/authority header.
        let sub_authorities = unsafe { *bytes.add(ACCESS_ALLOWED_ACE_PREFIX + 1) };
        if sub_authorities > SID_MAX_SUB_AUTHORITIES {
            return Ok(false);
        }
        let declared_sid_size = SID_HEADER_SIZE + usize::from(sub_authorities) * 4;
        if declared_sid_size > ace_size - ACCESS_ALLOWED_ACE_PREFIX {
            return Ok(false);
        }
        // SAFETY: complete declared SID is now bounded inside this native-validated ACE.
        if unsafe { IsValidSid(ace_sid) } == 0 {
            return Ok(false);
        }
        // SAFETY: validated SID is bounded inside this ACE.
        let sid_length = unsafe { GetLengthSid(ace_sid) } as usize;
        if sid_length != declared_sid_size || ace_size != ACCESS_ALLOWED_ACE_PREFIX + sid_length {
            return Ok(false);
        }
        // SAFETY: both SID pointers remain valid for this final identity check.
        Ok(mask == FILE_ALL_ACCESS && unsafe { EqualSid(ace_sid, sid) } != 0)
    }

    /// The trustee of an `allow` ACE: `(is the current user, identifier authority, sub-authorities)`,
    /// or `None` when the ACE is too short or its SID is malformed.
    fn read_trustee(
        ace: *mut c_void,
        ace_size: usize,
        sid: *mut c_void,
    ) -> Option<(bool, u64, Vec<u32>)> {
        if ace_size < ACCESS_ALLOWED_ACE_PREFIX + SID_HEADER_SIZE {
            return None;
        }
        let bytes = ace.cast::<u8>();
        // SAFETY: the ACE is at least prefix + SID header long (checked above).
        let sub_authorities = unsafe { *bytes.add(ACCESS_ALLOWED_ACE_PREFIX + 1) };
        if sub_authorities > SID_MAX_SUB_AUTHORITIES {
            return None;
        }
        let declared = SID_HEADER_SIZE + usize::from(sub_authorities) * 4;
        if declared > ace_size - ACCESS_ALLOWED_ACE_PREFIX {
            return None;
        }
        // SAFETY: the complete declared SID lies inside this native-validated ACE.
        let ace_sid = unsafe { bytes.add(ACCESS_ALLOWED_ACE_PREFIX) }.cast::<c_void>();
        if unsafe { IsValidSid(ace_sid) } == 0 {
            return None;
        }
        let mut authority = 0u64;
        let mut subs = Vec::with_capacity(usize::from(sub_authorities));
        // SAFETY: authority bytes and each sub-authority lie inside the declared SID.
        unsafe {
            for i in 0..6 {
                authority =
                    (authority << 8) | u64::from(*bytes.add(ACCESS_ALLOWED_ACE_PREFIX + 2 + i));
            }
            for i in 0..usize::from(sub_authorities) {
                subs.push(std::ptr::read_unaligned(
                    bytes
                        .add(ACCESS_ALLOWED_ACE_PREFIX + SID_HEADER_SIZE + 4 * i)
                        .cast::<u32>(),
                ));
            }
        }
        // SAFETY: both SIDs are valid for this comparison.
        let is_user = unsafe { EqualSid(ace_sid, sid) } != 0;
        Some((is_user, authority, subs))
    }

    /// The tolerant form: every `allow` ACE must name an acceptable trustee (`ace_is_acceptable`).
    fn tolerant_dacl_verdict(
        dacl: *mut c_void,
        count: u32,
        sid: *mut c_void,
        shown: &Path,
    ) -> crate::error::Result<Trust> {
        for index in 0..count {
            let mut ace = std::ptr::null_mut();
            // SAFETY: `index` is below the count of a native-validated ACL.
            if unsafe { GetAce(dacl, index, &mut ace) } == 0 {
                return Err(FsError::io(shown, std::io::Error::last_os_error()));
            }
            if ace.is_null() {
                return Ok(Trust::ForeignAccess);
            }
            // SAFETY: GetAce returned an ACE from native-validated ACL storage.
            let header = unsafe { &*(ace.cast::<AceHeader>()) };
            let trustee = if ace_kind(header.ace_type) == AceKind::Allow {
                read_trustee(ace, usize::from(header.ace_size), sid)
            } else {
                None
            };
            let view = trustee
                .as_ref()
                .map(|(user, authority, subs)| (*user, *authority, subs.as_slice()));
            if !ace_is_acceptable(header.ace_type, header.ace_flags, view) {
                return Ok(Trust::ForeignAccess);
            }
        }
        Ok(Trust::Private)
    }

    require_persistent_acls(file, shown)?;
    let token = current_process_token_user(shown)?;
    // SAFETY: TOKEN_USER starts with a SID pointer inside the retained allocation.
    let sid = unsafe { *(token.as_ptr().cast::<*mut c_void>()) };
    let mut owner = std::ptr::null_mut();
    let mut dacl = std::ptr::null_mut();
    let mut descriptor = std::ptr::null_mut();
    // SAFETY: live handle; returned pointers live until LocalFree(descriptor).
    let result = unsafe {
        GetSecurityInfo(
            file.as_raw_handle(),
            SE_FILE_OBJECT,
            OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION,
            &mut owner,
            std::ptr::null_mut(),
            &mut dacl,
            std::ptr::null_mut(),
            &mut descriptor,
        )
    };
    if result != 0 {
        return Err(FsError::io(
            shown,
            std::io::Error::from_raw_os_error(result as i32),
        ));
    }
    let check = (|| -> crate::error::Result<Trust> {
        if descriptor.is_null() || owner.is_null() {
            return Ok(Trust::ForeignOwner);
        }
        // A NULL DACL grants everyone full access.
        if dacl.is_null() {
            return Ok(Trust::ForeignAccess);
        }
        let directory = file
            .metadata()
            .map_err(|error| FsError::io(shown, error))?
            .is_dir();
        let mut control = 0;
        let mut revision = 0;
        // SAFETY: descriptor came from GetSecurityInfo and remains live for this query.
        if unsafe { GetSecurityDescriptorControl(descriptor, &mut control, &mut revision) } == 0 {
            return Err(FsError::io(shown, std::io::Error::last_os_error()));
        }
        if !tolerant && control & SE_DACL_PROTECTED == 0 {
            return Ok(Trust::ForeignAccess);
        }
        // The owner is the current user, or an enabled token group (Administrators when
        // elevated). The strict form's single ACE below still has to name the current user.
        if !owner_matches_token(owner, sid, shown)? {
            return Ok(Trust::ForeignOwner);
        }
        // SAFETY: native validator rejects malformed ACL data before indexed access.
        if unsafe { IsValidAcl(dacl) } == 0 {
            return Ok(Trust::ForeignAccess);
        }
        let mut info = AclSizeInformation {
            ace_count: 0,
            acl_bytes_in_use: 0,
            acl_bytes_free: 0,
        };
        // SAFETY: valid ACL and correctly sized output structure.
        if unsafe {
            GetAclInformation(
                dacl,
                (&mut info as *mut AclSizeInformation).cast(),
                std::mem::size_of::<AclSizeInformation>() as u32,
                ACL_SIZE_INFORMATION,
            )
        } == 0
        {
            return Err(FsError::io(shown, std::io::Error::last_os_error()));
        }
        if tolerant {
            return tolerant_dacl_verdict(dacl, info.ace_count, sid, shown);
        }
        let private = strict_single_ace(dacl, info.ace_count, directory, sid, shown)?;
        Ok(if private {
            Trust::Private
        } else {
            Trust::ForeignAccess
        })
    })();
    // SAFETY: GetSecurityInfo allocated this descriptor on success, including all returned views.
    unsafe { LocalFree(descriptor) };
    check
}

/// Verify the current owner-only state of this exact handle. This never repairs permissions,
/// removes an entry, or reopens a displayed path. Later permission changes remain possible.
pub(crate) fn verify_owner_only_handle(
    file: &std::fs::File,
    shown: &Path,
) -> crate::error::Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let metadata = file.metadata().map_err(|error| FsError::io(shown, error))?;
        // SAFETY: geteuid has no preconditions.
        if metadata.uid() != unsafe { libc::geteuid() } {
            return Err(FsError::NotOwned(shown.to_path_buf()));
        }
        if metadata.mode() & 0o077 != 0 {
            return Err(FsError::TooPermissive(shown.to_path_buf()));
        }
        crate::acl::refuse_acl(file, shown)
    }
    #[cfg(windows)]
    {
        if is_owner_only_handle(file, shown)? {
            Ok(())
        } else {
            Err(FsError::TooPermissive(shown.to_path_buf()))
        }
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = (file, shown);
        Err(FsError::Unavailable(
            "owner-only handle verification requires Unix or Windows",
        ))
    }
}

/// Whether the pinned object's owner is exactly `sid` (the reverify after an owner rewrite).
#[cfg(windows)]
fn handle_owner_is(
    file: &std::fs::File,
    sid: *mut std::ffi::c_void,
    path: &Path,
) -> crate::error::Result<bool> {
    use std::ffi::c_void;
    use std::os::windows::io::AsRawHandle;
    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn GetSecurityInfo(
            object: *mut c_void,
            object_type: u32,
            information: u32,
            owner: *mut *mut c_void,
            group: *mut *mut c_void,
            dacl: *mut *mut c_void,
            sacl: *mut *mut c_void,
            descriptor: *mut *mut c_void,
        ) -> u32;
        fn EqualSid(left: *mut c_void, right: *mut c_void) -> i32;
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn LocalFree(memory: *mut c_void) -> *mut c_void;
    }
    const SE_FILE_OBJECT: u32 = 1;
    const OWNER_SECURITY_INFORMATION: u32 = 0x0000_0001;
    let mut owner = std::ptr::null_mut();
    let mut descriptor = std::ptr::null_mut();
    // SAFETY: live handle; the owner view lives until LocalFree(descriptor).
    let result = unsafe {
        GetSecurityInfo(
            file.as_raw_handle(),
            SE_FILE_OBJECT,
            OWNER_SECURITY_INFORMATION,
            &mut owner,
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            &mut descriptor,
        )
    };
    if result != 0 {
        return Err(FsError::io(
            path,
            std::io::Error::from_raw_os_error(result as i32),
        ));
    }
    // SAFETY: both SIDs are live for this comparison.
    let same = !owner.is_null() && unsafe { EqualSid(owner, sid) } != 0;
    // SAFETY: GetSecurityInfo allocated this descriptor on success.
    unsafe { LocalFree(descriptor) };
    Ok(same)
}

#[cfg(windows)]
fn native_restrict_owner_only(file: &std::fs::File, path: &Path) -> crate::error::Result<()> {
    use std::ffi::c_void;
    use std::os::windows::io::AsRawHandle;
    const DACL_SECURITY_INFORMATION: u32 = 0x0000_0004;
    const PROTECTED_DACL_SECURITY_INFORMATION: u32 = 0x8000_0000;
    const SE_FILE_OBJECT: u32 = 1;
    const OWNER_SECURITY_INFORMATION: u32 = 0x0000_0001;

    #[link(name = "advapi32")]
    unsafe extern "system" {
        fn GetSecurityInfo(
            object: *mut c_void,
            object_type: u32,
            information: u32,
            owner: *mut *mut c_void,
            group: *mut *mut c_void,
            dacl: *mut *mut c_void,
            sacl: *mut *mut c_void,
            descriptor: *mut *mut c_void,
        ) -> u32;
        fn SetSecurityInfo(
            object: *mut c_void,
            object_type: u32,
            information: u32,
            owner: *mut c_void,
            group: *mut c_void,
            dacl: *mut c_void,
            sacl: *mut c_void,
        ) -> u32;
        fn GetSecurityDescriptorDacl(
            descriptor: *mut c_void,
            present: *mut i32,
            dacl: *mut *mut c_void,
            defaulted: *mut i32,
        ) -> i32;
        fn EqualSid(left: *mut c_void, right: *mut c_void) -> i32;
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn LocalFree(memory: *mut c_void) -> *mut c_void;
    }

    require_persistent_acls(file, path)?;
    // Determine inheritance from the pinned object rather than looking the path up again.
    let directory = file
        .metadata()
        .map_err(|error| FsError::io(path, error))?
        .is_dir();
    let token_info = current_process_token_user(path)?;
    unsafe {
        let sid = *(token_info.as_ptr().cast::<*mut c_void>());
        let mut owner = std::ptr::null_mut();
        let mut descriptor = std::ptr::null_mut();
        let owner_result = GetSecurityInfo(
            file.as_raw_handle(),
            SE_FILE_OBJECT,
            OWNER_SECURITY_INFORMATION,
            &mut owner,
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            std::ptr::null_mut(),
            &mut descriptor,
        );
        if owner_result != 0 {
            return Err(FsError::io(
                path,
                std::io::Error::from_raw_os_error(owner_result as i32),
            ));
        }
        // Accept the current user or an enabled token group: elevated processes create objects
        // owned by BUILTIN\\Administrators. A foreign owner is refused here, never taken over.
        // A trusted group owner is rewritten to the token user below (an unelevated process is
        // not the enabled-group owner, so leaving it would strand the repair); a refused
        // WRITE_OWNER is the typed I/O error of the SetSecurityInfo call, never a success.
        // SAFETY: both SIDs are live for this comparison (owner until LocalFree below).
        let is_token_user = !owner.is_null() && EqualSid(owner, sid) != 0;
        let owned = owner_matches_token(owner, sid, path);
        LocalFree(descriptor);
        let owned = owned?;
        if !owned {
            return Err(FsError::NotOwned(path.to_path_buf()));
        }
        let descriptor = SecurityDescriptor::owner_only(path, directory)?;
        let mut present = 0;
        let mut dacl = std::ptr::null_mut();
        let mut defaulted = 0;
        if GetSecurityDescriptorDacl(descriptor.0, &mut present, &mut dacl, &mut defaulted) == 0 {
            return Err(FsError::io(path, std::io::Error::last_os_error()));
        }
        if present == 0 || dacl.is_null() {
            return Err(FsError::Unavailable("owner-only descriptor lacks DACL"));
        }
        // Inheritable ACEs on a directory are propagated by SetSecurityInfo to existing children
        // that inherit; this call only guarantees the pinned object itself ends owner-only. The
        // owner member is set in the same call when it is not already the token user, so the
        // object never sits with a protected user DACL under a foreign-to-unelevated owner.
        let (information, new_owner) = if is_token_user {
            (
                DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION,
                std::ptr::null_mut(),
            )
        } else {
            (
                OWNER_SECURITY_INFORMATION
                    | DACL_SECURITY_INFORMATION
                    | PROTECTED_DACL_SECURITY_INFORMATION,
                sid,
            )
        };
        let result = SetSecurityInfo(
            file.as_raw_handle(),
            SE_FILE_OBJECT,
            information,
            new_owner,
            std::ptr::null_mut(),
            dacl,
            std::ptr::null_mut(),
        );
        if result == 0 {
            verify_owner_only_handle(file, path)?;
            if !is_token_user && !handle_owner_is(file, sid, path)? {
                return Err(FsError::NotOwned(path.to_path_buf()));
            }
            Ok(())
        } else {
            Err(crate::error::FsError::io(
                path,
                std::io::Error::from_raw_os_error(result as i32),
            ))
        }
    }
}

/// A security descriptor built from SDDL: explicit TokenUser owner plus one protected ACE giving
/// that user full control,
/// freed on drop. A directory's ACE also inherits to what is created inside it. Used to create
/// files and directories owner-only from the start, with no window in which a wider inherited ACL
/// applies.
#[cfg(windows)]
pub(crate) struct SecurityDescriptor(pub(crate) *mut std::ffi::c_void);

#[cfg(windows)]
impl SecurityDescriptor {
    pub(crate) fn owner_only(shown: &Path, directory: bool) -> crate::error::Result<Self> {
        use std::ffi::c_void;
        #[link(name = "advapi32")]
        unsafe extern "system" {
            fn ConvertStringSecurityDescriptorToSecurityDescriptorW(
                string: *const u16,
                revision: u32,
                descriptor: *mut *mut c_void,
                size: *mut u32,
            ) -> i32;
        }
        let sid = current_process_sid_string(shown)?;
        let inherit = if directory { "OICI" } else { "" };
        let sddl: Vec<u16> = format!("O:{sid}D:P(A;{inherit};FA;;;{sid})")
            .encode_utf16()
            .chain(Some(0))
            .collect();
        let mut raw = std::ptr::null_mut();
        // SAFETY: NUL-terminated SDDL; the API allocates the returned descriptor.
        if unsafe {
            ConvertStringSecurityDescriptorToSecurityDescriptorW(
                sddl.as_ptr(),
                1,
                &mut raw,
                std::ptr::null_mut(),
            )
        } == 0
        {
            return Err(FsError::io(shown, std::io::Error::last_os_error()));
        }
        Ok(Self(raw))
    }
}

#[cfg(windows)]
impl Drop for SecurityDescriptor {
    fn drop(&mut self) {
        #[link(name = "kernel32")]
        unsafe extern "system" {
            fn LocalFree(memory: *mut std::ffi::c_void) -> *mut std::ffi::c_void;
        }
        // SAFETY: allocation returned by ConvertStringSecurityDescriptorToSecurityDescriptorW.
        unsafe { LocalFree(self.0) };
    }
}

/// Exclusively creates `path` for writing with the owner-only security descriptor passed to
/// `CreateFileW`, so the file never exists with the parent's inherited ACL (no principal that ACL
/// admits can open it before it is restricted). Fails if the descriptor cannot be built, or if
/// `path` exists (a link at the name is never followed: `CREATE_NEW` refuses an existing name).
#[cfg(windows)]
pub(crate) fn create_new_owner_only(path: &Path) -> std::io::Result<std::fs::File> {
    use std::ffi::c_void;
    use std::os::windows::ffi::OsStrExt;
    use std::os::windows::io::FromRawHandle;

    #[repr(C)]
    struct SecurityAttributes {
        length: u32,
        descriptor: *mut c_void,
        inherit_handle: i32,
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn CreateFileW(
            name: *const u16,
            access: u32,
            share: u32,
            security: *const c_void,
            disposition: u32,
            flags: u32,
            template: *mut c_void,
        ) -> *mut c_void;
    }
    const GENERIC_WRITE: u32 = 0x4000_0000;
    const READ_CONTROL: u32 = 0x0002_0000;
    const DELETE: u32 = 0x0001_0000;
    const FILE_SHARE_READ_WRITE_DELETE: u32 = 0x7;
    const CREATE_NEW: u32 = 1;
    const FILE_ATTRIBUTE_NORMAL: u32 = 0x80;

    let descriptor = SecurityDescriptor::owner_only(path, false).map_err(std::io::Error::other)?;
    let attributes = SecurityAttributes {
        length: std::mem::size_of::<SecurityAttributes>() as u32,
        descriptor: descriptor.0,
        inherit_handle: 0,
    };
    let wide: Vec<u16> = path.as_os_str().encode_wide().chain(Some(0)).collect();
    if wide[..wide.len() - 1].contains(&0) {
        return Err(std::io::Error::from(std::io::ErrorKind::InvalidInput));
    }
    // SAFETY: `wide` is NUL-terminated and `attributes` (with the descriptor it points to) outlives
    // the call; the handle is owned by the returned `File` on success.
    let handle = unsafe {
        CreateFileW(
            wide.as_ptr(),
            GENERIC_WRITE | READ_CONTROL | DELETE,
            FILE_SHARE_READ_WRITE_DELETE,
            (&attributes as *const SecurityAttributes).cast(),
            CREATE_NEW,
            FILE_ATTRIBUTE_NORMAL,
            std::ptr::null_mut(),
        )
    };
    if handle as isize == -1 {
        return Err(std::io::Error::last_os_error());
    }
    // SAFETY: CreateFileW returned a fresh handle that nothing else owns.
    let file = unsafe { std::fs::File::from_raw_handle(handle) };
    if let Err(error) = verify_owner_only_handle(&file, path) {
        let _ = discard_unverified_owner_only(&file, path);
        return Err(error.into());
    }
    Ok(file)
}

/// Mark an empty just-created object for deletion through its current handle. No path lookup runs
/// between failed privacy verification and cleanup.
#[cfg(windows)]
pub(crate) fn discard_unverified_owner_only(
    file: &std::fs::File,
    shown: &Path,
) -> crate::error::Result<()> {
    use std::os::windows::io::AsRawHandle;
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn SetFileInformationByHandle(
            file: *mut std::ffi::c_void,
            class: i32,
            info: *const std::ffi::c_void,
            size: u32,
        ) -> i32;
    }
    const FILE_DISPOSITION_INFO: i32 = 4;
    let delete: u8 = 1;
    // SAFETY: live handle was opened with DELETE; BOOL buffer is correctly sized.
    if unsafe {
        SetFileInformationByHandle(
            file.as_raw_handle(),
            FILE_DISPOSITION_INFO,
            (&delete as *const u8).cast(),
            1,
        )
    } == 0
    {
        return Err(FsError::io(shown, std::io::Error::last_os_error()));
    }
    Ok(())
}

/// Create a private directory through its retained native handle. Verification and cleanup use
/// that exact created object, so a namespace replacement cannot turn failed verification into
/// deletion of another directory.
#[cfg(windows)]
fn create_dir_owner_only(path: &Path) -> std::io::Result<()> {
    use std::ffi::c_void;
    use std::os::windows::ffi::OsStrExt;
    use std::os::windows::io::{AsRawHandle, FromRawHandle};

    #[repr(C)]
    struct UnicodeString {
        length: u16,
        maximum_length: u16,
        buffer: *mut u16,
    }
    #[repr(C)]
    struct ObjectAttributes {
        length: u32,
        root_directory: *mut c_void,
        object_name: *mut UnicodeString,
        attributes: u32,
        security_descriptor: *mut c_void,
        security_quality_of_service: *mut c_void,
    }
    #[repr(C)]
    struct IoStatusBlock {
        status: usize, // NTSTATUS / pointer union; matches the other NtCreateFile declarations.
        information: usize,
    }
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn CreateFileW(
            name: *const u16,
            access: u32,
            share: u32,
            security: *const c_void,
            disposition: u32,
            flags: u32,
            template: *mut c_void,
        ) -> *mut c_void;
        fn GetFileInformationByHandleEx(
            file: *mut c_void,
            class: i32,
            info: *mut c_void,
            size: u32,
        ) -> i32;
    }
    #[link(name = "ntdll")]
    unsafe extern "system" {
        fn NtCreateFile(
            file: *mut *mut c_void,
            access: u32,
            attributes: *mut ObjectAttributes,
            status: *mut IoStatusBlock,
            allocation_size: *const i64,
            file_attributes: u32,
            share: u32,
            disposition: u32,
            options: u32,
            ea_buffer: *const c_void,
            ea_length: u32,
        ) -> i32;
        fn RtlNtStatusToDosError(status: i32) -> u32;
    }
    const FILE_ADD_SUBDIRECTORY: u32 = 0x4;
    const READ_ATTRIBUTES: u32 = 0x80;
    const READ_CONTROL: u32 = 0x0002_0000;
    const SYNCHRONIZE: u32 = 0x0010_0000;
    const DELETE: u32 = 0x0001_0000;
    const OPEN_EXISTING: u32 = 3;
    const FILE_SHARE_READ_WRITE: u32 = 0x3;
    const FILE_FLAG_BACKUP_SEMANTICS: u32 = 0x0200_0000;
    const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
    const FILE_ATTRIBUTE_TAG_INFO: i32 = 9;
    const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x400;
    const FILE_ATTRIBUTE_DIRECTORY: u32 = 0x10;
    const FILE_CREATE: u32 = 2;
    const FILE_DIRECTORY_FILE: u32 = 0x1;
    const FILE_WRITE_THROUGH: u32 = 0x2;
    const FILE_SYNCHRONOUS_IO_NONALERT: u32 = 0x20;
    const FILE_OPEN_REPARSE_POINT: u32 = 0x0020_0000;

    #[repr(C)]
    struct AttributeTagInfo {
        attributes: u32,
        tag: u32,
    }

    let parent = match path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        Some(parent) => parent.to_path_buf(),
        None => std::env::current_dir()?,
    };
    let name = path
        .file_name()
        .ok_or_else(|| std::io::Error::from(std::io::ErrorKind::InvalidInput))?;
    let mut child: Vec<u16> = name.encode_wide().collect();
    if child.is_empty()
        || child
            .iter()
            .any(|unit| *unit == 0 || *unit == b'\\' as u16 || *unit == b'/' as u16)
    {
        return Err(std::io::Error::from(std::io::ErrorKind::InvalidInput));
    }
    let child_bytes = u16::try_from(child.len() * 2)
        .map_err(|_| std::io::Error::from(std::io::ErrorKind::InvalidInput))?;
    let mut child_name = UnicodeString {
        length: child_bytes,
        maximum_length: child_bytes,
        buffer: child.as_mut_ptr(),
    };
    let parent_wide: Vec<u16> = parent.as_os_str().encode_wide().chain(Some(0)).collect();
    if parent_wide[..parent_wide.len() - 1].contains(&0) {
        return Err(std::io::Error::from(std::io::ErrorKind::InvalidInput));
    }
    // Another creator can still hold DELETE on this freshly created parent while
    // verifying it (and retaining the ability to discard a failed creation).
    // Keep our no-delete-sharing pin; wait only for that transient sharing refusal.
    // Never turn access denial, a missing parent, or a persistent lock into success.
    let mut attempt = 0;
    let parent_raw = loop {
        // SAFETY: NUL-terminated parent path; a successful handle is adopted below.
        let raw = unsafe {
            CreateFileW(
                parent_wide.as_ptr(),
                FILE_ADD_SUBDIRECTORY | READ_ATTRIBUTES | SYNCHRONIZE,
                FILE_SHARE_READ_WRITE,
                std::ptr::null(),
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                std::ptr::null_mut(),
            )
        };
        if !raw.is_null() && raw as isize != -1 {
            break raw;
        }
        let error = std::io::Error::last_os_error();
        if error.raw_os_error() != Some(32) || attempt + 1 >= crate::replaced::MAX_OPEN_TRIES {
            return Err(error);
        }
        std::thread::sleep(crate::replaced::pause_after(attempt));
        attempt += 1;
    };
    // SAFETY: CreateFileW returned an owned parent-directory handle.
    let parent_file = unsafe { std::fs::File::from_raw_handle(parent_raw) };
    let mut tag = AttributeTagInfo {
        attributes: 0,
        tag: 0,
    };
    // SAFETY: parent handle is live and output buffer has exact AttributeTagInfo size.
    if unsafe {
        GetFileInformationByHandleEx(
            parent_file.as_raw_handle(),
            FILE_ATTRIBUTE_TAG_INFO,
            (&mut tag as *mut AttributeTagInfo).cast(),
            std::mem::size_of::<AttributeTagInfo>() as u32,
        )
    } == 0
    {
        return Err(std::io::Error::last_os_error());
    }
    if tag.attributes & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
        return Err(FsError::Symlink(parent).into());
    }
    let descriptor = SecurityDescriptor::owner_only(path, true).map_err(std::io::Error::from)?;
    let mut attributes = ObjectAttributes {
        length: std::mem::size_of::<ObjectAttributes>() as u32,
        root_directory: parent_file.as_raw_handle(),
        object_name: &mut child_name,
        attributes: 0x40, // OBJ_CASE_INSENSITIVE
        security_descriptor: descriptor.0,
        security_quality_of_service: std::ptr::null_mut(),
    };
    let mut status = IoStatusBlock {
        status: 0,
        information: 0,
    };
    let mut raw = std::ptr::null_mut();
    // SAFETY: pinned parent, one checked component, and descriptor buffers all remain live.
    let result = unsafe {
        NtCreateFile(
            &mut raw,
            READ_ATTRIBUTES | READ_CONTROL | SYNCHRONIZE | DELETE,
            &mut attributes,
            &mut status,
            std::ptr::null(),
            FILE_ATTRIBUTE_DIRECTORY,
            FILE_SHARE_READ_WRITE,
            FILE_CREATE,
            FILE_DIRECTORY_FILE
                | FILE_WRITE_THROUGH
                | FILE_SYNCHRONOUS_IO_NONALERT
                | FILE_OPEN_REPARSE_POINT,
            std::ptr::null(),
            0,
        )
    };
    if result < 0 {
        // SAFETY: RtlNtStatusToDosError converts this API's NTSTATUS result.
        return Err(std::io::Error::from_raw_os_error(
            unsafe { RtlNtStatusToDosError(result) } as i32,
        ));
    }
    if raw.is_null() || raw as isize == -1 {
        return Err(std::io::Error::from(std::io::ErrorKind::Other));
    }
    // SAFETY: NtCreateFile returned one owned handle to precisely the object it created.
    let file = unsafe { std::fs::File::from_raw_handle(raw) };
    if let Err(error) = verify_owner_only_handle(&file, path) {
        let _ = discard_unverified_owner_only(&file, path);
        return Err(error.into());
    }
    Ok(())
}

#[cfg(test)]
mod owner_policy_tests {
    use super::*;

    const USER: &str = "S-1-5-21-1-2-3-1001";
    const ADMINS: &str = "S-1-5-32-544";
    const SYSTEM: &str = "S-1-5-18";
    const OTHER_USER: &str = "S-1-5-21-1-2-3-1002";

    const EVERYONE: &str = "S-1-1-0";
    const LOCAL: &str = "S-1-2-0";
    const INTERACTIVE: &str = "S-1-5-4";
    const AUTH_USERS: &str = "S-1-5-11";
    const USERS: &str = "S-1-5-32-545";
    const ENABLED_GROUP: u32 = SE_GROUP_ENABLED | 0x1; // ENABLED | MANDATORY

    fn broad(sid: &&str) -> bool {
        match *sid {
            "S-1-1-0" => sid_is_broad(1, &[0]),
            "S-1-2-0" => sid_is_broad(2, &[0]),
            "S-1-5-4" => sid_is_broad(5, &[4]),
            "S-1-5-11" => sid_is_broad(5, &[11]),
            "S-1-5-32-545" => sid_is_broad(5, &[32, 545]),
            _ => false,
        }
    }

    fn trusted(owner: &&str, groups: &[(&str, u32)]) -> bool {
        owner_is_trusted(owner, &USER, groups, &broad)
    }

    #[test]
    fn current_user_owner_is_trusted() {
        assert!(trusted(&USER, &[]));
    }

    #[test]
    fn administrators_owner_needs_owner_and_enabled_flags() {
        assert!(trusted(
            &ADMINS,
            &[(ADMINS, SE_GROUP_OWNER | SE_GROUP_ENABLED)]
        ));
        // Enabled but not an owner group: rejected.
        assert!(!trusted(&ADMINS, &[(ADMINS, SE_GROUP_ENABLED)]));
        // Owner but not enabled (filtered token, deny-only): rejected.
        assert!(!trusted(
            &ADMINS,
            &[(ADMINS, SE_GROUP_OWNER | SE_GROUP_USE_FOR_DENY_ONLY)]
        ));
        assert!(!trusted(
            &ADMINS,
            &[(
                ADMINS,
                SE_GROUP_OWNER | SE_GROUP_ENABLED | SE_GROUP_USE_FOR_DENY_ONLY
            )]
        ));
        assert!(!trusted(&ADMINS, &[]));
    }

    #[test]
    fn broad_groups_are_never_trusted_owners() {
        for sid in [EVERYONE, LOCAL, INTERACTIVE, AUTH_USERS, USERS] {
            // Enabled and mandatory, not an owner group.
            assert!(!trusted(&sid, &[(sid, ENABLED_GROUP)]), "{sid}");
            // Hard-deny holds even when the token flags the group as an owner.
            assert!(
                !trusted(&sid, &[(sid, ENABLED_GROUP | SE_GROUP_OWNER)]),
                "{sid}"
            );
        }
    }

    #[test]
    fn broad_sid_shapes() {
        assert!(sid_is_broad(1, &[0]) && sid_is_broad(5, &[32, 545]));
        assert!(!sid_is_broad(5, &[32, 544]) && !sid_is_broad(5, &[18]));
    }

    #[test]
    fn foreign_owner_is_rejected() {
        let groups = [(ADMINS, SE_GROUP_OWNER | SE_GROUP_ENABLED)];
        assert!(!trusted(&OTHER_USER, &groups));
        assert!(!trusted(&SYSTEM, &groups));
    }
}

/// The tolerant DACL policy (rightkit#517 / #676), pure so it runs on every platform: which ACEs may
/// appear on an object that still counts as owner-only.
#[cfg(test)]
mod dacl_policy_tests {
    use super::*;

    const SYSTEM: (u64, &[u32]) = (5, &[18]);
    const ADMINS: (u64, &[u32]) = (5, &[32, 544]);
    const CREATOR_OWNER: (u64, &[u32]) = (3, &[0]);
    const EVERYONE: (u64, &[u32]) = (1, &[0]);
    const USERS: (u64, &[u32]) = (5, &[32, 545]);
    const AUTH_USERS: (u64, &[u32]) = (5, &[11]);
    const INTERACTIVE: (u64, &[u32]) = (5, &[4]);
    const OTHER_USER: (u64, &[u32]) = (5, &[21, 1, 2, 3, 1002]);
    const ALLOW: u8 = 0;
    const DENY: u8 = 1;
    const INHERITED: u8 = 0x10;
    const OICI: u8 = 0x03;

    fn allow(trustee: (u64, &[u32]), is_user: bool, flags: u8) -> bool {
        ace_is_acceptable(ALLOW, flags, Some((is_user, trustee.0, trustee.1)))
    }

    #[test]
    fn the_current_user_system_and_administrators_are_accepted_inherited_or_explicit() {
        // %LOCALAPPDATA% inherits exactly these three.
        assert!(allow(OTHER_USER, true, INHERITED | OICI));
        assert!(allow(SYSTEM, false, INHERITED | OICI));
        assert!(allow(ADMINS, false, INHERITED | OICI));
        assert!(allow(SYSTEM, false, 0));
        assert!(allow(ADMINS, false, OICI));
    }

    #[test]
    fn another_user_or_a_broad_group_is_rejected_whatever_the_flags() {
        for (name, trustee) in [
            ("other user", OTHER_USER),
            ("Everyone", EVERYONE),
            ("Users", USERS),
            ("Authenticated Users", AUTH_USERS),
            ("INTERACTIVE", INTERACTIVE),
        ] {
            for flags in [0, INHERITED, OICI, INHERITED | OICI, INHERIT_ONLY_ACE] {
                assert!(!allow(trustee, false, flags), "{name} flags {flags:#x}");
            }
        }
    }

    #[test]
    fn creator_owner_counts_only_when_inherit_only() {
        assert!(allow(CREATOR_OWNER, false, INHERIT_ONLY_ACE | OICI));
        assert!(!allow(CREATOR_OWNER, false, OICI));
        assert!(!allow(CREATOR_OWNER, false, 0));
    }

    #[test]
    fn deny_aces_are_ignored_and_unknown_types_fail_closed() {
        for deny in [1u8, 6, 10, 12] {
            assert!(ace_is_acceptable(deny, 0, None), "deny type {deny}");
            assert!(ace_is_acceptable(
                deny,
                0,
                Some((false, EVERYONE.0, EVERYONE.1))
            ));
        }
        // Object allow (5), compound allow (4), unknown (0x7f), system audit (2), mandatory label (17).
        for other in [2u8, 3, 4, 5, 7, 8, 11, 13, 14, 15, 16, 17, 0x7f, 0xff] {
            assert!(
                !ace_is_acceptable(other, 0, Some((true, 5, &[18]))),
                "type {other}"
            );
        }
        assert_eq!(ace_kind(ALLOW), AceKind::Allow);
        assert_eq!(ace_kind(9), AceKind::Allow);
        assert_eq!(ace_kind(DENY), AceKind::Deny);
    }

    #[test]
    fn an_allow_ace_with_an_unreadable_trustee_is_rejected() {
        assert!(!ace_is_acceptable(ALLOW, 0, None));
        assert!(!ace_is_acceptable(9, OICI, None));
    }

    #[test]
    fn a_broad_trustee_cannot_pose_as_the_current_user_by_authority() {
        // Only the explicit `is_current_user` bit (an `EqualSid` against the token) counts.
        assert!(!allow(EVERYONE, false, 0));
        assert!(!allow((5, &[18, 1]), false, 0));
        assert!(!allow((5, &[32, 544, 1]), false, 0));
        assert!(!allow((5, &[]), false, 0));
        assert!(!allow((6, &[18]), false, 0));
    }
}

