        assert!(err.is_not_found(), "{err:?}");
    }

    #[test]
    fn a_directory_is_not_a_file() {
        let dir = tempfile::tempdir().unwrap();
        let err = open_read_nofollow(dir.path(), &ReadOptions::new()).unwrap_err();
