        let strict = ReadOptions::new().require_single_link(true);
        assert!(open_read_nofollow(&path, &strict).is_ok());
        std::fs::hard_link(&path, dir.path().join("alias")).unwrap();
        let err = open_read_nofollow(&path, &strict).unwrap_err();
